    #region GridFormulaEngine Class


    /// <summary>
        /// Encapsulates the code required to parse and compute formulas. Hashtable
        /// properties maintain a Formula Library of functions as well as a list
        /// of dependent cells.
        /// <para/>
        /// You can add and remove library functions.
        /// </summary>
#if SILVERLIGHT
		public class GridFormulaEngine:IDisposable
#else
        public class GridFormulaEngine : Disposable
#endif
        {

            //the grid
            public const double machineepsilon = 5E-16;
            public const double maxrealnumber = 1E300;
            public const double minrealnumber = 1E-300;
            private GridModel grid;
            public double ACC = 4.0;
            public double BIGNO = 1.0e10;
            public double BIGNI = 1.0e-10;
            private static void besselmfirstcheb(double c,
  ref double b0,
  ref double b1,
  ref double b2)
            {
                b0 = c;
                b1 = 0.0;
                b2 = 0.0;
            }

            private static void besselmnextcheb(double x,
               double c,
               ref double b0,
               ref double b1,
               ref double b2)
            {
                b2 = b1;
                b1 = b0;
                b0 = x * b1 - b2 + c;
            }

            private static void besselm1firstcheb(double c,
               ref double b0,
               ref double b1,
               ref double b2)
            {
                b0 = c;
                b1 = 0.0;
                b2 = 0.0;
            }

            private static void besselm1nextcheb(double x,
               double c,
               ref double b0,
               ref double b1,
               ref double b2)
            {
                b2 = b1;
                b1 = b0;
                b0 = x * b1 - b2 + c;
            }
