            static GridFormulaEngine()
            {
                if (!string.IsNullOrEmpty(CultureInfo.CurrentCulture.NumberFormat.CurrencyDecimalSeparator))
                    ParseDecimalSeparator = CultureInfo.CurrentCulture.NumberFormat.CurrencyDecimalSeparator[0];
                if (!string.IsNullOrEmpty(CultureInfo.CurrentCulture.NumberFormat.CurrencyGroupSeparator))
                    ParseArgumentSeparator = CultureInfo.CurrentCulture.NumberFormat.CurrencyGroupSeparator[0];
            }
            private bool suspendRefresh = false;
