                    {
                        this.errorStrings = new ArrayList();
                        this.errorStrings.AddRange(new string[]
                    {
                        "#N/A", "#VALUE!", "#REF!", "#DIV/0!", "#NUM!", "#NAME?", "#NULL!"
                    });
