            /// <summary>
            /// Returns the subtotal of input range(s).
            /// </summary>
            /// <param name="args">A list of cell references(seperated by commas) with Number to Indicate the function</param>
            /// <returns> A string holding result of the Specified Function. (i.e)Subtotal of range(s)</returns>            
            public string ComputeSubTotal(string args)
            {
                string cellReference = string.Empty;
                double val;
                DateTime dateValue;
                int index = 0;
                string[] arg = args.Split(new char[] { ParseArgumentSeparator }).ToArray();
                int argCount = arg.GetLength(0);
 
                if (argCount < 2)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                if (this.IsCellReference(arg[0]))
                {
                    cellReference = GetValueFromArg(arg[0]);
                }
                else
                {
                    cellReference = arg[0];
                }

                if (double.TryParse(cellReference, out val))
                {
                    index = (int)val;
                    if (index < 1 || index > 111||(index>11 && index<101))
                    {
                        return "#VALUE?";
                    }
                }
                else if (DateTime.TryParse(cellReference, out dateValue))
                {
                    val = GetSerialDateTimeFromDate(dateValue);
                    index = (int)val;
                    if (index < 1 || index > 111 || (index > 11 && index < 101))
                    {
                        return "#VALUE?";
                    }
                }

                cellReference = args.Remove(0, arg[0].Length+1);

                switch (index)
                {
                    case 1:
                        return this.ComputeAvg(cellReference);

                    case 2:
                        return this.ComputeCount(cellReference);
                        
                    case 3:
                        return this.ComputeCounta(cellReference);

                    case 4:
                        return this.ComputeMax(cellReference);

                    case 5:
                        return this.ComputeMin(cellReference);

                    case 6:
                        return this.ComputeProduct(cellReference);

                    case 7:
                        return this.ComputeStdev(cellReference);

                    case 8:
                        return this.ComputeStdevp(cellReference);

                    case 9:
                        return this.ComputeSum(cellReference);

                    case 10:
                        return this.ComputeVar(cellReference);

                    case 11:
                        return this.ComputeVarp(cellReference);

                    case 101:
                        return this.ComputeAvg(cellReference, false);

                    case 102:
                        return this.ComputeCount(cellReference,false);

                    case 103:
                        return this.ComputeCounta(cellReference, false);

                    case 104:
                        return this.ComputeMax(cellReference, false);

                    case 105:
                        return this.ComputeMin(cellReference, false);

                    case 106:
                        return this.ComputeProduct(cellReference, false);

                    case 107:
                        return this.ComputeStdev(cellReference, false);

                    case 108:
                        return this.ComputeStdevp(cellReference, false);

                    case 109:
                        return this.ComputeSum(cellReference, false);

                    case 110:
                        return this.ComputeVar(cellReference, false);

                    case 111:
                        return this.ComputeVarp(cellReference, false);

                    default:
                        return "#VALUE?";

                }                
                
            }

