                    && double.TryParse(GetValueFromArg(range[1]), NumberStyles.Any, null, out d2))
                {
                    if (d1 * d2 <= 0)
                        return "#NUM!";
                    d3 = Math.Ceiling(d1 / d2) * d2;
                    if (d2 > 0)
                    {
                        while (d3 > d1)
