                    if (d1 * d2 <= 0)
                        return "#NUM!";
                    d3 = Math.Ceiling(d1 / d2) * d2;
                    if (d2 > 0)
                    {
                        while (d3 > d1)
                            d3 -= d2;
                    }
                    else
                    {
                        while (d3 < d1)
                            d3 -= d2;
                    }
                }
                else if (double.TryParse(GetValueFromArg(range[0]), NumberStyles.Any, null, out d1)
                         && DateTime.TryParse(GetValueFromArg(range[1]), out dateValue2))
                {
                    d2 = GetSerialDateTimeFromDate(dateValue2);
                    if (d1 * d2 <= 0)
                        return "#NUM!";
                    d3 = Math.Ceiling(d1 / d2) * d2;
                    if (d2 > 0)
                    {
                        while (d3 > d1)
                            d3 -= d2;
                    }
                    else
                    {
                        while (d3 < d1)
                            d3 -= d2;
                    }
                }
                else if (DateTime.TryParse(GetValueFromArg(range[0]), out dateValue1)
                         && double.TryParse(GetValueFromArg(range[1]), NumberStyles.Any, null, out d2))
                {
                    d1 = GetSerialDateTimeFromDate(dateValue1);
                    if (d1 * d2 <= 0)
                        return "#NUM!";
                    d3 = Math.Ceiling(d1 / d2) * d2;
                    if (d2 > 0)
                    {
                        while (d3 > d1)
                            d3 -= d2;
                    }
                    else
                    {
                        while (d3 < d1)
