            /// <summary>
            /// Computes the sum of range2
            /// if the item in the range1 satisfies the condition.
            /// </summary>
            /// <param name="range">Range1, condition, range2.</param>
            /// <returns>The conditional sum.</returns>
            public string ComputeSumIf(string range)
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 2 && argCount != 3)
                {
                    return FormulaErrorStrings[wrong_number_arguments];
                }
                string criteriaRange = args[0];
                string criteria = args[1];//.Replace(TIC, "");

                if (criteria.Length < 1)
                {
                    return "0";
                }

                char op = TOKEN_equal;

                if (criteria[0] != this.TIC[0] && "=><".IndexOf(criteria[0]) == -1)
                {
                    ////cell reference
                    criteria = this.GetValueFromArg(criteria);
                }

                int offset = (criteria.Length > 0 && criteria[0] == this.TIC[0]) ? 1 : 0;
                double compare = double.MinValue;
                if (criteria.Substring(offset).StartsWith(">="))
                {
                    criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                    op = TOKEN_greatereq;
                }
                else if (criteria.Substring(offset).StartsWith("<="))
                {
                    criteria = criteria.Substring(offset + 2, criteria.Length - 2 - 2 * offset);
                    op = TOKEN_lesseq;
                }
                else if (criteria.Substring(offset).StartsWith("<"))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                    op = TOKEN_less;
                }
                else if (criteria.Substring(offset).StartsWith(">"))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                    op = TOKEN_greater;
                }
                else if (criteria.Substring(offset).StartsWith("="))
                {
                    criteria = criteria.Substring(offset + 1, criteria.Length - 1 - 2 * offset);
                }

                criteria = criteria.Replace(this.TIC, "");
                bool numeric = double.TryParse(criteria, out compare);

                string sumRange = (argCount == 2) ? criteriaRange : args[2];                

                string[] s1 = this.GetCellsFromArgs(criteriaRange);
                string[] s2 = this.GetCellsFromArgs(sumRange);


                double sum = 0;
                int count = s1.GetLength(0);
                double d;
                DateTime dateValue;
                double[] vector = new double[count];
                string s;

                for (int index = 0; index < count; ++index)
                {
                    bool result;

                    if(numeric)
                        result=this.CheckCriteria(op, s1[index], compare);
                    else
                        result= this.CheckCriteria(op, s1[index], criteria);

                    if (result)
                    {
                        s = s2[index];
                        s = this.GetValueFromArg(s);
                        if (double.TryParse(s, NumberStyles.Any, null, out d))
                        {
                            sum += d;
                        }
                        else if (DateTime.TryParse(s, out dateValue))
                        {
                            d = GetSerialDateTimeFromDate(dateValue);
                            sum += d;
                        }
                    }
                }
                                
                return sum.ToString();
                //			string[] ss = range.Split(new char[]{ParseArgumentSeparator});
                //			if(ss.GetLength(0) != 3) 
                //			{
                //				return FormulaErrorStrings[requires_3_args];
                //			}
                //			else 
                //			{
                //				string[] s1 = this.GetCellsFromArgs(ss[0]);
                //				string[] s2 = this.GetCellsFromArgs(ss[2]);
                //
                //			
