                        // Actual/365
                        factor = double.Parse(ComputeYearFrac(string.Format("{0},{1},{2}", settle, matur, basis)));
                        break;
                    case 4:
                        // European 30/360
                        factor = double.Parse(ComputeYearFrac(string.Format("{0},{1},{2}", settle, matur, basis)));
