            /// <summary>
            ///  Returns the discount rate for a security.
            /// </summary>
            /// <param name="args">Number and the number of digits</param>
            /// <returns>Rate of Discount</returns>
            public string ComputeDisc(string args)
            {
                string discount = string.Empty;
                try
                {
                    string[] argsArray = SplitArgsPreservingQuotedCommas(args);
                    string Settlementdate = argsArray[0];
                    string Maturitydate = argsArray[1];
                    string Price = argsArray[2];
                    string Redemptionvalue = argsArray[3];
                    string Basis = string.Empty;
                    if (argsArray.Length > 4)
                        Basis = argsArray[4];
                    else
                        Basis = "0";
                    Settlementdate = this.GetValueFromArg(Settlementdate);
                    Maturitydate = this.GetValueFromArg(Maturitydate);
                    Price = this.GetValueFromArg(Price);
                    Redemptionvalue = this.GetValueFromArg(Redemptionvalue);
                    Basis = this.GetValueFromArg(Basis);
                    DateTime date1, date2 = DateTime.Now;
                    double settlement = 0;
                    double maturity = 0;
                    if ((DateTime.TryParse(Settlementdate, out date1) || double.TryParse(Settlementdate, out settlement))
                   && (DateTime.TryParse(Maturitydate, out date2) || double.TryParse(Maturitydate, out maturity)))
                    {
                        if (settlement == 0)
                            settlement = date1.ToOADate();
                        if (maturity == 0)
                            maturity = date2.ToOADate();

                        double DSM = double.Parse(ComputeDays360(settlement + "," + maturity)) + 1;
                        switch (Basis)
                        {
                            case "0":
                                Basis = "360";
                                break;
                            case "1":
                                Basis = "365";
                                break;
                            case "2":
                                Basis = (DSM / 360).ToString();
                                break;
                            case "3":
                                Basis = (DSM / 365).ToString();
                                break;
                            case "4":
                                Basis = "30";
                                break;
                        }
                        double disc = (((double.Parse(Redemptionvalue) - double.Parse(Price)) / double.Parse(Redemptionvalue)) * (double.Parse(Basis) / DSM));
                        discount = disc.ToString();
                    }
                }
                catch (Exception)
                {                    
                }

                return discount;
            }

            public string ComputeCUMIPMT(string args)
            {
                double interest = 0;
                try
                {

                    string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });

                    if (argsArray.Length < 5)
                    {
                        return this.FormulaErrorStrings[wrong_number_arguments];
                    }
                    string s1 = argsArray[0];
                    string s2 = argsArray[1];
                    string s3 = argsArray[2];
                    string s4 = argsArray[3];
                    string s5 = argsArray[4];
                    string s6 = argsArray[5];
                    s1 = this.GetValueFromArg(s1);
                    s2 = this.GetValueFromArg(s2);
                    s3 = this.GetValueFromArg(s3);
                    s4 = this.GetValueFromArg(s4);
                    s5 = this.GetValueFromArg(s5);
                    s6 = this.GetValueFromArg(s6);

                    double rate = 0, periods = 0, value = 0, start = 0, end = 0, type = 0;
                    if (!double.TryParse(s1, out rate) ||
                     !double.TryParse(s2, out periods) ||
                     !double.TryParse(s3, out value) ||
                     !double.TryParse(s4, out start) ||
                     !double.TryParse(s5, out end) ||
                     !double.TryParse(s6, out type))
                    {

                        return ErrorStrings[1].ToString();
                    }

                    // Return error if either rate, periods, or value are lower than or equal to zero
                    if (rate <= 0 || periods <= 0 || value <= 0)
                    {
                        return this.ErrorStrings[1].ToString();
                    }

                    // Return error if start < 1, end < 1, or start > end
                    if (start < 1 || end < 1 || start > end)
                    {
                        return this.ErrorStrings[1].ToString();
                    }

                    // Return error if type is neither 0 nor 1
                    if (type != 0 && type != 1)
                    {
                        return this.ErrorStrings[4].ToString();
                    }

                    // Compute cumulative interest
                    double payment = double.Parse(ComputePmt(string.Format("{0},{1},{2},{3},{4}", rate, periods, value, 0, type)));

                    interest = 0;
                    if (start == 1)
                    {
                        if (type == 0)
                        {
                            interest = -value;
                            start++;
                        }
                    }
                    for (int i = (int)start; i <= end; i++)
                    {
                        if (type == 1)
                        {
                            interest += double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 2, payment, value, 1))) - payment;
                        }
                        else
                        {
                            interest += double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 1, payment, value, 0)));
                        }
                    }
                    interest *= rate;



                }
                catch (Exception ex)
                {
                    return ex.Message;
                }
                // Return cumulative interest
                return interest.ToString();
            }
            public string ComputeCUMPRINC(string args)
            {
                double principal = 0;
                try
                {

                    string[] argsArray = args.Split(new char[] { ParseArgumentSeparator });
                    if (argsArray.Length < 5)
                    {
                        return this.FormulaErrorStrings[wrong_number_arguments];
                    }
                    string s1 = argsArray[0];
                    string s2 = argsArray[1];
                    string s3 = argsArray[2];
                    string s4 = argsArray[3];
                    string s5 = argsArray[4];
                    string s6 = argsArray[5];
                    s1 = this.GetValueFromArg(s1);
                    s2 = this.GetValueFromArg(s2);
                    s3 = this.GetValueFromArg(s3);
                    s4 = this.GetValueFromArg(s4);
                    s5 = this.GetValueFromArg(s5);
                    s6 = this.GetValueFromArg(s6);

                    double rate = 0, periods = 0, value = 0, start = 0, end = 0, type = 0;
                    if (!double.TryParse(s1, out rate) ||
                   !double.TryParse(s2, out periods) ||
                   !double.TryParse(s3, out value) ||
                   !double.TryParse(s4, out start) ||
                   !double.TryParse(s5, out end) ||
                   !double.TryParse(s6, out type))
                    {

                        return ErrorStrings[1].ToString();
                    }

                    // Return error if either rate, periods, or value are lower than or equal to zero
                    if (rate <= 0 || periods <= 0 || value <= 0)
                    {
                        return this.ErrorStrings[1].ToString();
                    }

                    // Return error if start < 1, end < 1, or start > end
                    if (start < 1 || end < 1 || start > end)
                    {
                        return this.ErrorStrings[1].ToString();
                    }

                    // Return error if type is neither 0 nor 1
                    if (type != 0 && type != 1)
                    {
                        return this.ErrorStrings[4].ToString();
                    }

                    double payment = double.Parse(ComputePmt(string.Format("{0},{1},{2},{3},{4}", rate, periods, value, 0, type)));

                    if (start == 1)
                    {
                        if (type == 0)
                        {
                            principal = payment + value * rate;
                        }
                        else
                        {
                            principal = payment;
                        }
                        start++;
                    }
                    for (double i = start; i <= end; i++)
                    {
                        if (type > 0)
                        {
                            principal += payment - (double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 2, payment, value, 1))) - payment) * rate;
                        }
                        else
                        {
                            principal += payment - double.Parse(ComputeFv(string.Format("{0},{1},{2},{3},{4}", rate, i - 1, payment, value, 0))) * rate;
                        }
                    }
                }
                catch (Exception ex)
                {
                    return ex.Message;
                }
                // Return cumulative interest
                return principal.ToString();

            }            
            
            private bool Daysfeb29(DateTime sDate, DateTime eDate)
            {
                DateTime sDateFeb = new DateTime(sDate.Year, 2, 1);
                DateTime eDateFeb = new DateTime(eDate.Year, 2, 1);
                int sDateDiff_1 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));
                int eDateDiff_1 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(sDateFeb.ToShortDateString()));

                int sDateDiff_2 = int.Parse(this.ComputeDatevalue(sDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));
                int eDateDiff_2 = int.Parse(this.ComputeDatevalue(eDate.ToShortDateString())) - int.Parse(this.ComputeDatevalue(eDateFeb.ToShortDateString()));

                if (DateTime.IsLeapYear(sDate.Year) && sDateDiff_1 < 0 && eDateDiff_1 >= 0)
                    return true;
                if (DateTime.IsLeapYear(eDate.Year) && sDateDiff_2 < 0 && eDateDiff_2 >= 0)
                    return true;
                return false;
            }
           

            /// <summary>
            /// The inverse of Cosh.
            /// </summary>
            /// <param name="args">Value >= 1.</param>
            /// <returns>ACosh(value).</returns>
            public string ComputeAcosh(string args)
            {
                double z;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out z)
                    && z >= 1)
                {
                    z = Math.Log(z + Math.Sqrt(z * z - 1));
                }
                else if (DateTime.TryParse(GetValueFromArg(args), out dateValue))
                {
                    z = GetSerialDateTimeFromDate(dateValue);
                    z = Math.Log(z + Math.Sqrt(z * z - 1));
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return z.ToString();
            }

            /// <summary>
            /// The inverse of Sinh.
            /// </summary>
            /// <param name="args">Value.</param>
            /// <returns>ASinh(value).</returns>
            public string ComputeAsinh(string args)
            {
                double z;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out z))
                {
                    z = Math.Sign(z) * Math.Log(Math.Abs(z) + Math.Sqrt(z * z + 1));
                }
                else if (DateTime.TryParse(GetValueFromArg(args), out dateValue))
                {
                    z = GetSerialDateTimeFromDate(dateValue);
                    z = Math.Sign(z) * Math.Log(Math.Abs(z) + Math.Sqrt(z * z + 1));
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return z.ToString();
            }

            /// <summary>
            /// The inverse of Tanh.
            /// </summary>
            /// <param name="args">|Value| &lt; 1.</param>
            /// <returns>ATanh(value).</returns>
            public string ComputeAtanh(string args)
            {
                double z;
                double z1;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out z)
                    && ((z1 = Math.Abs(z)) < 1))
                {
                    z = .5 * Math.Sign(z) * Math.Log((1 + z1) / (1 - z1));
                }
                else if (DateTime.TryParse(GetValueFromArg(args), out dateValue))
                {
                    z = GetSerialDateTimeFromDate(dateValue);
                    if ((z1 = Math.Abs(z)) < 1)
                        z = .5 * Math.Sign(z) * Math.Log((1 + z1) / (1 - z1));
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return z.ToString();
            }

            /// <summary>
            /// The ArcTangent of the x and y values. 
            /// </summary>
            /// <param name="argList">x_value and y_value.</param>
            /// <returns>Angle whose tangent is y_value/x_value.</returns>
            public string ComputeAtan2(string argList)
            {

                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 2)
                {
                    return FormulaErrorStrings[this.requires_2_args];
                }
                double x;
                double y;
                DateTime dateValue1, dateValue2;
                double atan2 = 0;
                if (double.TryParse(GetValueFromArg(args[0]), NumberStyles.Any, null, out x)
                    && double.TryParse(GetValueFromArg(args[1]), NumberStyles.Any, null, out y))
                {
                    atan2 = Math.Atan2(y, x);
                }
                else if (DateTime.TryParse(GetValueFromArg(args[0]), out dateValue1)
                 && DateTime.TryParse(GetValueFromArg(args[1]), out dateValue2))
                {
                    x = GetSerialDateTimeFromDate(dateValue1);
                    y = GetSerialDateTimeFromDate(dateValue2);
                    atan2 = Math.Atan2(y, x);
                }
                else if (double.TryParse(GetValueFromArg(args[0]), NumberStyles.Any, null, out x)
                         && DateTime.TryParse(GetValueFromArg(args[1]), out dateValue2))
                {
                    y = GetSerialDateTimeFromDate(dateValue2);
                    atan2 = Math.Atan2(y, x);
                }
                else if (DateTime.TryParse(GetValueFromArg(args[0]), out dateValue1)
                         && double.TryParse(GetValueFromArg(args[1]), NumberStyles.Any, null, out y))
                {
                    x = GetSerialDateTimeFromDate(dateValue1);
                    atan2 = Math.Atan2(y, x);
                }

                else
                    return FormulaErrorStrings[invalid_arguments];
                return atan2.ToString();
            }

