            /// <summary>
            /// Rounds up to larger in magnitude even number.
            /// </summary>
            /// <param name="args">Number to be rounded.</param>
            /// <returns>Rounded even value.</returns>
            public string ComputeEven(string args)
            {
                double number;
                double even = 0;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out number))
                {
                    int sgn = Math.Sign(number);
                    number = Math.Abs(number);
                    if ((int)number != number)
                        number = (int)(number + 1);

                    if ((number % 2) == 1)
                        even = sgn * (number + 1);
                    else
                        even = sgn * number;

                }
                else if (DateTime.TryParse(GetValueFromArg(args), out dateValue))
                {
                    number = GetSerialDateTimeFromDate(dateValue);
                    int sgn = Math.Sign(number);
                    number = Math.Abs(number);
                    if ((int)number != number)
                        number = (int)(number + 1);

                    if ((number % 2) == 1)
                        even = sgn * (number + 1);
                    else
                        even = sgn * number;
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return even.ToString();
            }

            private static int[] factorialTable = new int[]{
                                                           1, 1, 2, 6, 24, 120, 720, 
                                                           5040, 40320, 362880, 3628800, 
                                                           39916800, 479001600};

            /// <summary>
            /// Factorial of a given number.
            /// </summary>
            /// <param name="args">x.</param>
            /// <returns>x!.</returns>
            public string ComputeFact(string args)
            {
                double number = 0;
                double fact = 0;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out number)
                    && number >= 0)
                {
                    int x = (int)number;
                    if (x > 12)
                    {
                        fact = factorialTable[12];
                        for (int i = 13; i <= x; i++)
                            fact *= i;
                    }
                    else
                        fact = factorialTable[x];
                }
                else if (DateTime.TryParse(GetValueFromArg(args), out dateValue))
                {
                    number = GetSerialDateTimeFromDate(dateValue);
                    int x = (int)number;
                    if (x > 12)
                    {
                        fact = factorialTable[12];
                        for (int i = 13; i <= x; i++)
                            fact *= i;
                    }
                    else
                        fact = factorialTable[x];
                }
                else if (number < 0)
                    return "#NUM!";
                else
                    return FormulaErrorStrings[invalid_arguments];
                return fact.ToString();
            }


