            /// <summary>
            /// Determines the MRound value for thr Given arguments.
            /// </summary>
            /// <param name="argsList">Number, Multiple</param>
            /// <returns>MRound value of the given number</returns>
            public string ComputeMRound(string argsList)
            {
                string[] args = argsList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);

                if (argCount != 2)
                    return this.FormulaErrorStrings[invalid_arguments];

                double numValue = 0;
                double roundValue = 0;
                double numberstr, mround;
                string roundedBaseStr;
                string numStr = this.GetValueFromArg(args[0]);
                string roundStr = this.GetValueFromArg(args[1]);

                if (roundStr == "0")
                    return roundStr;

                if (ComputeSign(numStr) != ComputeSign(roundStr))
                    return "#NUM!";
                else 
                {
                    if ((numStr.Length == 0 || double.TryParse(numStr, NumberStyles.Any, null, out numValue))
                    && (roundStr.Length == 0 || double.TryParse(roundStr, NumberStyles.Any, null, out roundValue)))
                    {
                        numberstr = numValue / roundValue;
                        roundedBaseStr = ComputeRound(numberstr.ToString());
                        double roundedBaseValue = double.Parse(roundedBaseStr);
                        mround = roundedBaseValue * roundValue;

                        if (ComputeSign(numStr).StartsWith("-"))
                        {
                            if (mround < numValue)
                                mround += roundValue;
                        }
                        else
                        {
                            if (mround > numValue)
                                mround -= roundValue;
                        }
                    }
                    else
                        return this.FormulaErrorStrings[invalid_arguments];                    

                }

                return mround.ToString();
            }


