                                arrayList++;
                            }
                            else if ((double.TryParse(this.GetValueFromArg(s), NumberStyles.Any, null, out number) || s.Length > 0) && (int)number < 0)
                                return "#NUM!";
                            else
                                return "#VALUE!";

                        }
                    }
                    else
                    {
                        if (double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out number) || r.Length > 0)
                        {
                            ranges2[arrayList] = (int)number;
                            arrayList++;
                        }
                        else if ((double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out number) || r.Length > 0) && (int)number < 0)
                            return "#NUM!";
                        else
                            return "#VALUE!";
                    }
                }

                if (ranges2.Length == 1)
                {
                    return ranges2[0].ToString();
                }
                int multi = ranges2[0] * ranges2[1];
                str = ranges2[0].ToString() + "," + ranges2[1].ToString();
                gcd = ComputeGCD(str);
                int lcm = multi / int.Parse(gcd);
                for (int i = 2; i < ranges2.Length; i++)
                {
                    multi = lcm * ranges2[i];
                    str = lcm.ToString() + "," + ranges2[i].ToString();
                    gcd = ComputeGCD(str);
                    lcm = multi / int.Parse(gcd);
                }

                return lcm.ToString();
            }

            /// <summary>
            /// 
            /// </summary>
            /// <param name="argsList"></param>
            /// <returns></returns>
            public string ComputeFactDouble(string argsList)
            {
                double number;
                double fact = 1;
                string[] numList=argsList.Split(new char[]{ParseArgumentSeparator});
                DateTime dateValue;
                if (numList.GetLength(0) > 1)
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                if (double.TryParse(this.GetValueFromArg(argsList), NumberStyles.Any, null, out number)
                && number >= 0)
                {
                    int x = (int)number;
                    int n = x;
                    if (x > 3)
                    {
                        while (n > 0)
                        {
                            fact = fact * n;
                            n = n - 2;
                        }
                    }
                    else if (x == 0)
                        fact = 1;
                    else
                        fact = x;
                }
                else if (DateTime.TryParse(this.GetValueFromArg(argsList), out dateValue))
                {
                    number = GetSerialDateTimeFromDate(dateValue);
                    int x = (int)number;
                    int n = x;
                    if (x > 3)
                    {
                        while (n > 0)
                        {
                            fact = fact * n;
                            n = n - 2;
                        }
                    }
                    else if (x == 0)
                        fact = 1;
                    else
                        fact = x;
                }
                else
                    return this.FormulaErrorStrings[invalid_arguments];

                return fact.ToString();
            }


            /// <summary>
            /// Rounds up to larger in magnitude odd number.
            /// </summary>
            /// <param name="args">Number to be rounded.</param>
            /// <returns>Rounded odd value.</returns>
            public string ComputeOdd(string args)
            {
                double number;
                double odd = 0;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out number))
                {
                    int sgn = Math.Sign(number);
                    number = Math.Abs(number);
                    if ((int)number != number)
                        number = (int)(number + 1);

                    if ((number % 2) == 0)
                        odd = sgn * (number + 1);
                    else
                        odd = sgn * number;

                }
                else if (DateTime.TryParse(this.GetValueFromArg(args), out dateValue))
                {
                    number = GetSerialDateTimeFromDate(dateValue);
                    int sgn = Math.Sign(number);
                    number = Math.Abs(number);
                    if ((int)number != number)
                        number = (int)(number + 1);

                    if ((number % 2) == 0)
                        odd = sgn * (number + 1);
                    else
                        odd = sgn * number;
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return odd.ToString();
            }

            /// <summary>
            /// Converts degrees into radians.
            /// </summary>
            /// <param name="args">Value in degrees.</param>
            /// <returns>Radians.</returns>
            public string ComputeRadians(string args)
            {
                double radians = 0;
                double degrees;
                DateTime dateValue;
                if (double.TryParse(GetValueFromArg(args), NumberStyles.Any, null, out degrees))
                {
                    radians = Math.PI * degrees / 180;
                }
                else if (DateTime.TryParse(this.GetValueFromArg(args), out dateValue))
                {
                    degrees = GetSerialDateTimeFromDate(dateValue);
                    radians = Math.PI * degrees / 180;
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return radians.ToString();
            }

            /// <summary>
            /// Rounds a number to a specified number of digits.
            /// </summary>
            /// <param name="argList">Number and number of digits.</param>
            /// <returns>Rounded number.</returns>
            public string ComputeRound(string argList)
            {

                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount == 1)
                    return ComputeMath(argList, new MathFunc(Math.Round)).ToString();

                if (argCount != 2)
                {
                    return FormulaErrorStrings[this.invalid_arguments];
                }
                double x = 0;
                double digits = 0;
                double round = 0;
                string numStr = GetValueFromArg(args[0]);
                string digStr = GetValueFromArg(args[1]);

                if ((numStr.Length == 0 || double.TryParse(numStr, NumberStyles.Any, null, out x))
                && (digStr.Length == 0 || double.TryParse(digStr, NumberStyles.Any, null, out digits)))
                {
                    if (digits > 0)
                        round = Math.Round(x, (int)digits);
                    else
                    {
                        double mult = Math.Pow(10, -digits);
                        round = Math.Round(x / mult) * mult;
                    }
                }
                else
                    return FormulaErrorStrings[invalid_arguments];
                return round.ToString();
            }

            /// <summary>
            /// Rounds a number to a specified number of digits.
            /// </summary>
            /// <param name="argList">Number and number of digits.</param>
            /// <returns>Rounded number.</returns>
            public string ComputeRounddown(string argList)
            {
                double x = 0;

                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount == 1)
                {
                    double.TryParse(GetValueFromArg(argList), NumberStyles.Any, null, out x);
                    x = x - .5 * Math.Sign(x);
                    return ComputeRound(string.Format("{0}", x));
                }
                else if (argCount != 2)
                {
                    return FormulaErrorStrings[this.invalid_arguments];
                }
                double digits = 0;
                double.TryParse(GetValueFromArg(args[0]), NumberStyles.Any, null, out x);
                double.TryParse(GetValueFromArg(args[1]), NumberStyles.Any, null, out digits);
                x = x - .5 * Math.Pow(10, -digits) * Math.Sign(x);
                return ComputeRound(string.Format("{0}{1}{2}", x, ParseArgumentSeparator, digits));
            }

            /// <summary>
            /// Rounds a number to a specified number of digits.
            /// </summary>
            /// <param name="argList">Number and number of digits.</param>
            /// <returns>Rounded number.</returns>
            public string ComputeRoundup(string argList)
            {

                double x = 0;

                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount == 1)
                {
                    double.TryParse(GetValueFromArg(argList), NumberStyles.Any, null, out x);
                    x = x + .5 * Math.Sign(x);
                    return ComputeRound(string.Format("{0}", x));
                }
                else if (argCount != 2)
                {
                    return FormulaErrorStrings[this.invalid_arguments];
                }
                double digits = 0;
                double.TryParse(GetValueFromArg(args[0]), NumberStyles.Any, null, out x);
                double.TryParse(GetValueFromArg(args[1]), NumberStyles.Any, null, out digits);
                x = x + .5 * Math.Pow(10, -digits) * Math.Sign(x);
                return ComputeRound(string.Format("{0}{1}{2}", x, ParseArgumentSeparator, digits));

            }


            /// <summary>
            /// 
            /// </summary>
            /// <param name="argsList"></param>
            /// <returns></returns>
            public string ComputeRoman(string argsList)
            {
                string[] args = argsList.Split(new char[] { ParseArgumentSeparator });
                string ans0 = string.Empty, ans1 = string.Empty, ans2 = string.Empty, ans3 = string.Empty, ans4 = string.Empty;
                int n = 0;
                double doubleNumber;
                if (args.Length > 2)
                    return this.FormulaErrorStrings[this.invalid_arguments];

                int[] ranges2 = new int[2];

                foreach (string r in args)
                {
                    try
                    {
                        if ((double.TryParse(this.GetValueFromArg(r), NumberStyles.Any, null, out doubleNumber) || r.Length > 0) && (int)doubleNumber >= 0)
                        {
                            ranges2[n] = (int)doubleNumber;
                            n++;
                        }
                        else
                            return "#VALUE!";
                    }
                    catch
                    {
                        return "N/A";
                    }
                }

                if (ranges2[0] < 0 || ranges2[0] > 3999)
                {
                    return "N/A";
                }
                if (ranges2[1] < 0 || ranges2[1] > 4)
                {
                    return this.FormulaErrorStrings[this.invalid_arguments];
                }

                int[] values = new int[] { 1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1 };
                string[] numerals = new string[] { "M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I" };
                StringBuilder result = new StringBuilder();
                int number = ranges2[0];
                string num = number.ToString();
                bool flag = true, containForty = false, containNinety = false, endsForty = false, endsNinety = false;
                for (int i = 0; i < 13; i++)
                {
                    while (number >= values[i])
                    {
                        number -= values[i];
                        result.Append(numerals[i]);
                    }
                }
                ans0 = result.ToString();
                if ((num.Contains("45")) || (num.Contains("46")) || (num.Contains("47")) || (num.Contains("48")) || (num.Contains("49")))
                    containForty = true;
                if ((num.Contains("95")) || (num.Contains("96")) || (num.Contains("97")) || (num.Contains("98")) || (num.Contains("99")))
                    containNinety = true;
                if ((num.EndsWith("45")) || (num.EndsWith("46")) || (num.EndsWith("47")) || (num.EndsWith("48")) || (num.EndsWith("49")))
                    endsForty = true;
                if ((num.EndsWith("95")) || (num.EndsWith("96")) || (num.EndsWith("97")) || (num.EndsWith("98")) || (num.EndsWith("99")))
                    endsNinety = true;

                if (!(containForty || containNinety))
                {
                    return result.ToString();
                }

                if (num.EndsWith("499") || num.EndsWith("999"))
                {
                    string temp = ans0;
                    ans1 = temp.Replace('C', 'L');
                    ans1 = ans1.Replace('X', 'V');
                    ans2 = ans1.Replace('L', 'X');
                    string[] sp = ans2.Split('V');
                    char[] arr = sp[1].ToCharArray();
                    char[] arr1 = sp[0].ToCharArray();
                    Array.Reverse(arr);
                    temp = new string(arr);
                    ans2 = new string(arr1);
                    ans2 = ans2 + temp;
                    ans3 = ans2.Replace('X', 'V');
                    string[] sp1 = ans3.Split('V');
                    char[] arr2 = sp1[1].ToCharArray();
                    Array.Reverse(arr2);
                    temp = new string(arr2);
                    for (int i = 0; i < sp.Length - 1; i++)
                        ans4 = (i != 1 ? ans4 + sp1[i] : ans4 + temp);
                    flag = false;
                }

                if (num.Contains("95") || num.Contains("96") || num.Contains("97") || num.Contains("98"))
                {
                    string str = "4";
                    str = str.Replace('4', num[num.IndexOf('9')]);
                    int digit = int.Parse(str);
                    if (digit == 4 || digit == 9)
                    {
                        ans1 = ans0.Replace('C', 'L');
                        int x = ans1.IndexOf('X');
                        string[] sp = ans1.Split('X');
                        int z = 0;
                        int i = 0;
                        for (i = 0; z < x + 1; i++)
                        {
                            z += sp[i].Length;
                        }
                        char[] arr = sp[1].ToCharArray();
                        Array.Reverse(arr);
                        ans1 = new string(arr);
                        int ans1Length = ans1.Length;
                        int ans1Length1 = ans1Length;
                        int k = 0;
                        for (k = 0; k < ans1Length1 - 2; k++)
                        {
                            ans1 = ans1 + ans1[ans1Length - 3];
                            ans1Length--;
                        }
                        ans1 = ans1.Substring(k);
                        ans1 = sp[0] + ans1;
                        string[] sp2 = ans1.Split('L');
                        ans2 = sp2[0] + "X";
                        for (int d = 1; d < sp2.Length; d++)
                        {
                            ans2 = ans2 + sp2[d];
                        }
                        string[] sp3 = ans2.Split('X');
                        char[] arr1 = sp3[1].ToCharArray();
                        Array.Reverse(arr1);
                        ans3 = new string(arr1);
                        int ans3Length = ans3.Length;
                        int ans3Length1 = ans3Length;
                        int k1 = 0;
                        for (k1 = 0; k1 < ans3Length1 - 2; k1++)
                        {
                            ans3 = ans3 + ans3[ans3Length - 3];
                            ans3Length--;
                        }
                        ans3 = ans3.Substring(k);
                        ans3 = sp3[0] + ans3;
                        ans4 = ans3;
                        flag = false;
                    }
                }

                if (flag && (endsForty || endsNinety))
                {
                    int x = ans0.IndexOf('X');
                    string[] sp = ans0.Split('X');
                    if (sp.Length == 2)
                    {
                        int z = 0;
                        int i = 0;
                        for (i = 0; z < x + 1; i++)
                            z += sp[i].Length;
                        char[] arr = sp[i - 1].ToCharArray();
                        Array.Reverse(arr);
                        ans1 = new string(arr);
                        int ans1Length = ans1.Length;
                        int ans1Length1 = ans1Length;
                        int k = 0;
                        for (k = 0; k < ans1Length1 - 2; k++)
                        {
                            ans1 = ans1 + ans1[ans1Length - 3];
                            ans1Length--;
                        }
                        ans1 = ans1.Substring(k);
                        ans2 = ans3 = ans4 = ans1 = sp[0] + ans1;
                    }

                    if (sp.Length == 3)
                    {
                        string temp = ans0;
                        int i;
                        ans1 = temp.Replace("X", "V");
                        string[] arrV = ans1.Split('V');
                        ans2 = "";
                        char[] arr = arrV[1].ToCharArray();
                        Array.Reverse(arr);
                        string revStr = new string(arr);
                        for (i = 0; i < arrV.Length; i++)
                            ans2 = (i == 1 ? ans2 + revStr : ans2 + arrV[i]);
                        ans3 = ans4 = ans2;
                    }
                }
                else if (flag && (!(endsForty || endsNinety)))
                {
                    int x = ans0.IndexOf('C');
                    string[] sp = ans0.Split('C');
                    if (sp.Length == 2)
                    {
                        int z = 0;
                        int i = 0;
                        for (i = 0; z < x + 1; i++)
                        {
                            z += sp[i].Length;
                        }
                        char[] arr = sp[i - 1].ToCharArray();
                        Array.Reverse(arr);
                        ans1 = new string(arr);
                        int ans1Length = ans1.Length;
                        int ans1Length1 = ans1Length;
                        int k = 0;
                        for (k = 0; k < ans1Length1 - 2; k++)
                        {
                            ans1 = ans1 + ans1[ans1Length - 3];
                            ans1Length--;
                        }
                        ans1 = ans1.Substring(k);
                        ans1 = sp[0] + ans1;
                        ans2 = ans3 = ans4 = ans1;
                    }
                    if (sp.Length == 3)
                    {
                        string temp = ans0;
                        int i;
                        ans1 = temp.Replace("C", "L");
                        string[] arrV = ans1.Split('L');
                        ans2 = string.Empty;
                        char[] arr = arrV[1].ToCharArray();
                        Array.Reverse(arr);
                        string revStr = new string(arr);
                        for (i = 0; i < arrV.Length; i++)
                        {
                            ans2 = ((i == 1) ? ans2 + revStr : ans2 + arrV[i]);
                        }
                        ans3 = ans4 = ans2;
                    }
                }
                else if (flag)
                {
                    return ans0;
                }
                switch (ranges2[1])
                {
                    case 1:
                        ans0 = ans1;
                        break;
                    case 2:
                        ans0 = ans2;
                        break;
                    case 3:
                        ans0 = ans3;
                        break;
                    case 4:
                        ans0 = ans4;
                        break;
                }

                return ans0;

            }

