            //Statistical functions
            private double[] GetDoubleArray(string range)
            {
                double d;
                string s1 = string.Empty;
                ArrayList x = new ArrayList();

                this.AdjustRangeArg(ref range);
                string[] ranges = SplitArgsPreservingQuotedCommas(range);
                foreach (string r in ranges)
                {
                    ////cell range
                    if (r.IndexOf(':') > -1)
                    {
                        foreach (string s in this.GetCellsFromArgs(r))
                        {
                            try
                            {
                                s1 = this.GetValueFromArg(s);
                            }
                            catch
                            {
                            }

                            ////ignore if empty
                            if (s1.Length > 0)
                            {
                                if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                                {
                                    x.Add(d);
                                }
                            }
                        }
                    }
                    else
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(r);
                        }
                        catch
                        {
                        }

                        if (s1.Length > 0)
                        {
                            if (double.TryParse(s1, NumberStyles.Number | NumberStyles.AllowExponent, null, out d))
                            {
                                x.Add(d);
                            }
                        }
                        else
                        {
                            x.Add(0d);
                        }
                    }
                }

#if !SILVERLIGHT
                return (double[])x.ToArray(typeof(double));
#else
            return x.OfType<double>().ToArray();
#endif
            }

            public string ComputeConfidenceT(string argList)
            {
                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double alpha;
                double s;
                double sz;
                double val = 0;

                for (int i = 0; i < argCount; ++i)
                {
                    args[i] = this.GetValueFromArg(args[i]);
                }

                if (double.TryParse(args[0], NumberStyles.Any, null, out alpha)
                    && double.TryParse(args[1], NumberStyles.Any, null, out s)
                    && double.TryParse(args[2], NumberStyles.Any, null, out sz))
                {

                    val = this.normalinv(1 - alpha + alpha / 2, 0, 1);
                    val = val * s / Math.Sqrt(sz);
                }
                return val.ToString();
            }

            /// <summary>
            /// Returns the skewness of a distribution based on a population a characterization of the degree of asymmetry of a distribution around its mean.
            /// </summary>
            /// <param name="range"> numbers or names, arrays, or reference that contain numbers</param>
            /// <returns>Skewness of a distribution.</returns>
            public string ComputeSkewP(string range)
            {
                double[] x = this.GetDoubleArray(range);
                int n = x.GetLength(0);

                if (n < 3)
                {
                    return this.FormulaErrorStrings[this.invalid_arguments];
                }

                double xbar = 0;
                double sdev = this.sd(x, out xbar);
                double skew = 0;
                for (int i = 0; i < n; ++i)
                {
                    skew += Math.Pow((x[i] - xbar) / sdev, 3);
                }
                return (n * skew / (n - 1) / (n - 2)).ToString();
            }

            /// <summary>
            /// Returns population covariance, the average of the products of deviations for each data point pair in two data sets. 
            /// </summary>
            /// <param name="range">range1, range2.</param>
            /// <returns>The covarianceP</returns>
            public string ComputeCovarianceP(string range)
            {  
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount != 2)                            
                    return this.FormulaErrorStrings[wrong_number_arguments];
                
                double[] y = this.GetDoubleArray(args[0]);
                double[] x = this.GetDoubleArray(args[1]);
                if (y.GetLength(0) == 1 && x.GetLength(0) == 1)
                {  
                    return this.ErrorStrings[3].ToString();//#Div/0!
                }
                int n = x.GetLength(0);
                if (n <= 0 || n != y.GetLength(0))                   
                    return this.FormulaErrorStrings[wrong_number_arguments];
                
                double mean1 = Mean(y);
                double mean2 = Mean(x);
                double result = 0;
                int ns = y.Length;
                for (var i = 0; i < n; i++)
                {
                    result += (y[i] - mean1) * (x[i] - mean2);
                }

                return (result / ns).ToString();
            }

            /// <summary>
            /// Returns the sample covariance, the average of the products of deviations for each data point pair in two data sets.
            /// </summary>
            /// <param name="range">range1, range2.</param>
            /// <returns>The covariances</returns>
            public string ComputeCovarianceS(string range)
            {
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount != 2)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double[] y = this.GetDoubleArray(args[0]);
                double[] x = this.GetDoubleArray(args[1]);
                int n = x.GetLength(0);

                if (n <= 0 || n != y.GetLength(0))
                    return this.FormulaErrorStrings[wrong_number_arguments];                

                double sumx = 0;
                double sumy = 0;
                for (int i = 0; i < n; ++i)
                {
                    sumx += x[i];
                    sumy += y[i];
                }

                sumx = sumx / n;
                sumy = sumy / n;

                double sumxy = 0;

                for (int i = 0; i < n; ++i)
                {
                    sumxy += (x[i] - sumx) * (y[i] - sumy);
                }

                return Covariance(y, x).ToString();//(sumxy / n).ToString();
            }

            public string ComputePercentileInc(string range)
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 2)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double k;
                string s1 = this.GetValueFromArg(args[1]);
                if (!double.TryParse(s1, NumberStyles.Any, null, out k) && (k < 0 || k > 1))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
                double ss = Convert.ToDouble(s1);
                if (ss == 0 || ss <= 0 || ss >= 1)
                {
                    return this.ErrorStrings[4].ToString();
                }
                double[] dd = this.GetDoubleArray(args[0]);
                int n = dd.GetLength(0);

                Array.Sort(dd);

                double h = 1d / (n - 1);
                double d = dd[n - 1];
                for (int i = 0; i < n - 1; ++i)
                {
                    if ((i + 1) * h > k)
                    {
                        k = (k - i * h) / h;
                        d = dd[i] + k * (dd[i + 1] - dd[i]);
                        break;
                    }
                }
                return d.ToString();
            }


            /// <summary>
            /// Returns the percentile position in the range.
            /// </summary>
            /// <param name="range">Range, k.</param>
            /// <returns>Percentile position.</returns>
            /// <remarks>K is a value between 0 and 1.</remarks>
            public string ComputePercentileExc(string range)
            {
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount != 2)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double k;
                string s1 = this.GetValueFromArg(args[1]);
                if (!double.TryParse(s1, NumberStyles.Any, null, out k) && (k < 0 || k > 1))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
                
                double ss = Convert.ToDouble(s1);
                if (ss == 0 || ss <= 0 || ss >= 1)
                {
                    return this.ErrorStrings[4].ToString();
                }

                
                double[] dd = this.GetDoubleArray(args[0]);
                int n = dd.GetLength(0);

                Array.Sort(dd);

                int num = dd.GetLength(0);
             
                if (k <= 1 / (num + 1) && k >= num / (num + 1))
                {
                    return this.ErrorStrings[4].ToString();
                }
                double l = k * (num + 1);

                return l.ToString();
            }

            public string ComputePercentrankExc(string range)
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 2 && argCount != 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double x;
                double signif = 3;
                string s1 = this.GetValueFromArg(args[1]);
                if (!double.TryParse(s1, NumberStyles.Any, null, out x))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
                else if (x == 0)
                {
                    return this.ErrorStrings[4].ToString();
                }

                if (argCount == 3)
                {
                    s1 = this.GetValueFromArg(args[2]);
                    if (!double.TryParse(s1, NumberStyles.Integer, null, out signif) && signif < 1)
                    {
                        return this.FormulaErrorStrings[invalid_arguments];
                    }
                }

                double[] dd = this.GetDoubleArray(args[0]);
                int n = dd.GetLength(0);

                Array.Sort(dd);

                double d = 1;
                for (int i = 0; i < n; ++i)
                {
                    if (dd[i] == x)
                    {
                        int k = 0;
                        while (k + i < n && dd[k + i] == x)
                        {
                            k++;
                        }

                        d = ((double)(i - 1)) / (i + n - i - k - 1);

                        if (i > 0 && dd[i - 1] < x)
                        {
                            double di = ((double)i) / (n - 1);
                            d = di + (d - di) * (1 - (x - dd[i - 1]) / (dd[i] - dd[i - 1]));
                        }

                        break;
                    }
                }
                string fmt = "0." + new string('#', (int)signif);
                return d.ToString(fmt);
            }

            /// <summary>
            /// Returns the percentage rank Inc in the range.
            /// </summary>
            /// <param name="range">Range, x, significant digits.</param>
            /// <returns>Percentile position.</returns>
            /// <remarks>Significant digits are optional, defaulting to 3.</remarks>
            public string ComputePercentrankInc(string range)
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount != 2 && argCount != 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }

                double x;
                double signif = 3;
                string s1 = this.GetValueFromArg(args[1]);
                if (!double.TryParse(s1, NumberStyles.Any, null, out x))
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }
                else if (x == 0)
                {
                }

                if (argCount == 3)
                {
                    s1 = this.GetValueFromArg(args[2]);
                    if (!double.TryParse(s1, NumberStyles.Integer, null, out signif) && signif < 1)
                    {
                        return this.FormulaErrorStrings[invalid_arguments];
                    }
                }
                double[] dd = this.GetDoubleArray(args[0]);
                int n = dd.GetLength(0);
                Array.Sort(dd);
                double num = range.Length;
                double m = dd.GetLength(0);
                double power = Math.Pow(10, signif);
                double result = 0;
                bool match = false;
                int i = 0;
                while (!match && i < m)
                {
                    if (x == Convert.ToDouble(dd[i]))
                    {
                        //result = range.IndexOf((dd[i]) / (num - 1));
                        match = true;
                    }
                    else if (x >= dd[i] && (x < dd[i + 1] || i == m - 1))
                    {
                        //  result = (range.IndexOf(dd[i) + (x - dd[i]) / (dd[i + 1] - dd[i])) / (n - 1);
                        match = true;
                    }
                    i++;
                }
                double d = (Math.Floor(result * power) / power);
                string fmt = "0." + new string('#', (int)signif);
                return d.ToString(fmt);
            }
            private double sdP(double[] x, out double xbar)
            {
                int n = x.GetLength(0);
                xbar = 0;
                for (int i = 0; i < n; ++i)
                {
                    xbar += x[i];
                }

                xbar = xbar / n;
                double sumx2 = 0;
                double d = 0;

                for (int i = 0; i < n; ++i)
                {
                    d = x[i] - xbar;
                    sumx2 += d * d;
                }

                return Math.Sqrt(sumx2 / n);
            }
