            /// <summary>
            /// The Irwin-Hall distribution results from the sum on n independent standard uniform variables
            /// </summary>
            /// <param name="x">The value at which to evaluate the distribution.</param>
            /// <param name="n">The number of standard uniform variables.</param>
            public static double IHProbDens(double x, int n)
            {
                if (x < 0 || x > n) return 0.0;
                double d = 0;
                for (int i = 0; i <= n; i++)
                    d += Math.Pow(-1, i) * Combinations(n, i) * Math.Pow(x - i, n - 1) * Math.Sign(x - i);
                d *= 0.5;
                d /= Factorial(n - 1);
                return d;
            }
            #region Combinations
            /// <summary>
            /// Returns the number of possible combinations of k objects from a set of n object. The order of the chosen objects does not matter.
            /// </summary>
            /// <param name="n">Number of objects</param>
            /// <param name="k">Number of objects chosen</param>
            public static double Combinations(int n, int k)
            {
                double logCombin = LogCombin(n, k);
                double combin = Math.Exp(logCombin);
                return Math.Round(combin, 0);
            }

            internal static double LogCombin(int n, int k)
            {
                return LogFactorial(n) - LogFactorial(k) - LogFactorial(n - k);
            }

            private static double LogFactorial(int x)
            {
                double lf = 0;
                for (int i = 2; i <= x; i++)
                    lf += Math.Log(i);
                return lf;
            }
            #endregion
            /// <summary>
            /// Returns n! 
            /// 0! = 1,otherwise n! = n * (n-1) * (n-2) * ... * 2 * 1,
            /// </summary>
            public static long Factorial(int n)
            {
                if (n < 0) throw new ArgumentException("Factorial not defined for negative n");
                if (n > 20) throw new ArgumentException("Answer will exceed max long");
                long fact = 1;
                for (int i = n; i > 0; i--)
                    fact *= i;
                return fact;
            }

