            }

            /// <summary>
            /// Calculates the Hexadecimal equivalent value for the given Octal value
            /// </summary>
            /// <param name="argList">Data to be converted.</param>
            /// <returns>The Converted Hexadecimal value.</returns>
            public string ComputeOctToHex(string argList)
            {
#if _ENABLETIMERS
              string ML = "ComputeOctToHex"; MarkTimeStart(ML);
#endif
                int charCount = 0;
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                string value = this.GetValueFromArg(ranges[0]).Replace(this.TIC, string.Empty);

                string result = string.Empty;

                if (ranges.Length > 1)
                    charCount = int.Parse(ranges[1]);
                try
                {
                    if (value.Length > 10)
                    {
                        return ErrorStrings[4].ToString();
                    }
                    else
                    {
                        result = result = BaseToBase(value, 8, 16);
                        if (ranges.Length > 1)
                        {
                            if (charCount >= result.Length && charCount <= 10)
                            {
                                result = result.PadLeft(charCount, '0');
                            }
                            else
                            {
                                return ErrorStrings[4].ToString();
                            }
                        }
                    }
                }
                catch (Exception)
                {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return this.ErrorStrings[4].ToString();
                }
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                return result;
            }

