            public string ComputeReal(string argList)
            {
#if _ENABLETIMERS
               string ML = "ComputeReal"; MarkTimeStart(ML);
#endif
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });

                if (ranges.Length > 1)
                    return FormulaErrorStrings[10].ToString();
                string value = ranges[0];

                //if (value.Contains(this.TIC))
                  //  value = ranges[0].Replace(this.TIC, string.Empty);
                //value = this.GetValueFromArg(ranges[0]);
                // Lookup sign
               // if (this.ComputeIsText(value) == TRUEVALUESTR && value.Contains(this.TIC) || value == "")
                //{
                   // return ErrorStrings[4].ToString();
                //}
                value = value.Replace(this.TIC, string.Empty);
                value = value.TrimEnd();
                int plus = value.IndexOf('+');
                int minus = value.IndexOf('-');
                if (plus == 0) plus = value.IndexOf('+', 1);
                if (minus == 0) minus = value.IndexOf('-', 1);

                // Lookup imaginary unit
                string last = value.Substring(value.Length - 1, 1);
                bool unit = (last == "i" || last == "j");

                if (plus >= 0 || minus >= 0)
                {
                    // Return error if imaginary unit is neither i nor j
                    if (!unit) return ErrorStrings[4].ToString();

                    // Return real coefficient of complex number
                    if (plus >= 0)
                    {

#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ((ComputeIsText(value.Substring(0, plus)) == TRUEVALUESTR)) ?
                        ErrorStrings[4].ToString() : value.Substring(0, plus);
                    }
                    else
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif

                        return (ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR || ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : value.Substring(0, minus);

                    }
                }
                else
                {
                    if (unit)
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return (ComputeIsText(value.Substring(0, value.Length - 1)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : "0";
                    }
                    else
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return (ComputeIsText(value) == TRUEVALUESTR) ? ErrorStrings[5].ToString() : value;
                    }
                }
            }

            public string ComputeImaginary(string argList)
            {
#if _ENABLETIMERS
               string ML = "ComputeImaginary"; MarkTimeStart(ML);
#endif
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                if (ranges.Length > 1)
                    return FormulaErrorStrings[10].ToString();
                string value = ranges[0];
                if (value.Contains(this.TIC))
                    value = ranges[0].Replace(this.TIC, string.Empty);
                if (value == "")
                {
                    return ErrorStrings[4].ToString();
                }

                // Normalize imaginary coefficient
                value = value.Replace("+i", "+1i").Replace("-i", "-1i").Replace("+j", "+1j").Replace("-j", "-1j");

                // Lookup sign
                int plus = value.IndexOf('+');
                int minus = value.IndexOf('-');
                if (plus == 0) plus = value.IndexOf('+', 1);
                if (minus == 0) minus = value.IndexOf('-', 1);

                // Lookup imaginary unit
                string last = value.Substring(value.Length - 1, 1);
                bool unit = (last == "i" || last == "j");

                if (plus >= 0 || minus >= 0)
                {
                    // Return error if imaginary unit is neither i nor j
                    if (!unit)
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ErrorStrings[4].ToString();

                    // Return imaginary coefficient of complex number
                    if (plus >= 0)
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return (this.ComputeIsText(value.Substring(0, plus)) == TRUEVALUESTR) ?
                        ErrorStrings[4].ToString() : value.Substring(plus + 1, (value.Length - plus) - 2);
                    }
                    else
                    {

#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ((this.ComputeIsText(value.Substring(0, minus - 1)) == TRUEVALUESTR) || (this.ComputeIsText(value.Substring(minus + 1, (value.Length - minus) - 2))) == TRUEVALUESTR) ?
                         ErrorStrings[4].ToString() : "-" + value.Substring(minus + 1, (value.Length - minus) - 2);
                    }
                }
                else
                {
                    if (unit)
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ((this.ComputeIsText(value.Substring(0, value.Length - 1))) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : value.Substring(0, value.Length - 1);
                    }
                    else
                    {
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ((this.ComputeIsText(value)) == TRUEVALUESTR) ? ErrorStrings[4].ToString() : "0";
                    }
                }
            }
            public string ComputeImABS(string argList)
            {
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                string result = this.GetValueFromArg(ranges[0]);

                if (ranges.Length > 1)
                    return FormulaErrorStrings[25].ToString();

                string x = ComputeReal(result);
                string y = ComputeImaginary(result);
                // Return error if either coefficient is not a number
                if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())
                {
                    return ErrorStrings[4].ToString();
                }
                try
                {
                    // Return absolute value of complex number
                    return Math.Sqrt(Math.Pow(int.Parse(x), 2) + Math.Pow(int.Parse(y), 2)).ToString();
                }
                catch (Exception)
                {
                    return this.FormulaErrorStrings[21].ToString();
                }
            }

            public string ComputeComplex(string argList)
            {
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                string value = this.GetValueFromArg(ranges[0]);
                value = value.Replace(this.TIC, string.Empty);
                string real = ranges[0];
                string imaginary = ranges[1];
                string suffix;

                if ((ranges.Length <= 3))
                {
                    // Return error if either number is a non-numeric value
                    if (this.ComputeIsText(real) == TRUEVALUESTR || this.ComputeIsText(imaginary) == TRUEVALUESTR) return "#VALUE!";

                    // Set suffix
                    if (ranges.Length == 3)
                        suffix = ranges[2];
                    else
                        suffix = "";
                    suffix = (suffix == "") ? "i" : suffix = ranges[2];
                    suffix = suffix.Replace(TIC, string.Empty);

                    // Return error if suffix is neither "i" nor "j"
                    if (suffix != "i" && suffix != "j")
                        return ErrorStrings[1].ToString();

                    // Return complex number
                    if (double.Parse(real) == 0 && double.Parse(imaginary) == 0)
                        return "0";
                    else if (double.Parse(real) == 0)
                    {
                        return
                            (double.Parse(imaginary) == 1) ? suffix : imaginary.ToString() + suffix;
                    }
                    else
                        if (double.Parse(imaginary) == 0)
                            return real;
                        else
                        {
                            string sign = (double.Parse(imaginary) > 0) ? "+" : " ";
                            return real + sign + ((double.Parse(imaginary) == 1) ? suffix : imaginary + suffix);
                        }
                }
                return null;
            }

            public string ComputeImaginarySum(string argList)
            {
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                string result = this.GetValueFromArg(ranges[0]);

                for (int i = 1; i < ranges.Length; i++)
                {
                    // Lookup coefficients of two complex numbers
                    string a = ComputeReal(result);
                    string b = ComputeImaginary(result);
                    string c = ComputeReal(ranges[i]);
                    string d = ComputeImaginary(ranges[i]);

                    // Return error if either coefficient is not a number
                    if (a == ErrorStrings[4].ToString() || b == ErrorStrings[4].ToString() || c == ErrorStrings[4].ToString() || d == ErrorStrings[4].ToString())
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                        return ErrorStrings[4].ToString();

                    // Complute product of two complex numbers
                    try
                    {
                        string num = (int.Parse(a) + int.Parse(c)).ToString() + ParseArgumentSeparator + (int.Parse(b) + int.Parse(d)).ToString();
                        result = ComputeComplex(num);
                    }

                    catch (Exception)
                    {

#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif

                        return this.ErrorStrings[4].ToString();

                    }
                }
#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                return result;
            }

