            /// Returns the LOG value of the given Complex Number.
            /// </summary>
            /// <param name="argList">Input Complex Number</param>
            /// <returns>The Log of the given Complex Number.</returns>
            public string ComputeIMLN(string argList)
            {
                string[] ranges = SplitArgsPreservingQuotedCommas(argList);

                string value;

                if (ranges.Length != 1)               
                        return FormulaErrorStrings[13].ToString();                
                else
                    value = this.GetValueFromArg(ranges[0]);

                string x = ComputeReal(value);
                string y = ComputeImaginary(value);

                // Lookup imaginary unit
                string unit = value.Substring(value.Length - 1);
                unit = (unit == "i" || unit == "j") ? unit : "i";

                try
                {
                    // Return error if either coefficient is not a number
                    if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString()) return ErrorStrings[4].ToString();
                    double a = double.Parse(x);
                    double b = double.Parse(y);
                    double r1 = Math.Log(Math.Sqrt(a * a + b * b));
                    double r2 = Math.Atan(b / a);

                    string args = r1.ToString() + ParseArgumentSeparator + r2.ToString() + ParseArgumentSeparator + unit;
                    // Return sine of complex number
                    return ComputeComplex(args);
                }

                catch
                {                    
                    if (ComputeIsText(value) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (value == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(value) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
                }
            }

            /// <summary>
            /// Returns the Exponent of the given Complex Number.
            /// </summary>
            /// <param name="argList">Input Complex Number</param>
            /// <returns>The Exponent of the given Complex Number.</returns>
            public string ComputeImEXP(string argList)
            {
                string[] ranges = SplitArgsPreservingQuotedCommas(argList);
                string result = this.GetValueFromArg(ranges[0]);
                result = result.Replace(this.TIC, "");

                // Return error if inumber is a logical value
                if (result == "true" || result == "false") return "#VALUE!";

                string x = ComputeReal(result);
                string y = ComputeImaginary(result);

                // Lookup imaginary unit
                string unit = result.Substring(result.Length - 1);
                unit = (unit == "i" || unit == "j") ? unit : "i";

                try
                {
                    // Return error if either coefficient is not a number
                    if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString())                  
                        return ErrorStrings[4].ToString();
                    
                    double a = double.Parse(x);
                    double b = double.Parse(y);

                    double e = Math.Exp(a);

                    double r1 = e * Math.Cos(b);
                    double r2 = e * Math.Sin(b);

                    string args = r1.ToString() + ParseArgumentSeparator + r2.ToString() + ParseArgumentSeparator + unit;
                    // Return sine of complex number
                    return ComputeComplex(args);
                }

                catch
                {
                    if (ComputeIsText(result) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "")
                        return ErrorStrings[1].ToString();
                    else if (double.Parse(result) < 0)
                        return ErrorStrings[4].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
                }
            }

            /// <summary>
            /// Returns the power of the given Complex Number.
            /// </summary>
            /// <param name="argList">Input Complex Number</param>
            /// <returns>The power of the given Complex Number.</returns>
            public string ComputeImPower(string argList)
            {
                string[] ranges = SplitArgsPreservingQuotedCommas(argList);
                string result, num;
                if (ranges.Length == 2)
                {
                    result = this.GetValueFromArg(ranges[0]);
                    result = result.Replace(this.TIC, "");
                    num = this.GetValueFromArg(ranges[1]);
                    num = num.Replace(this.TIC, "");
                }
                else
                {                   
                    return FormulaErrorStrings[wrong_number_arguments].ToString();
                }

                string x = ComputeReal(result);
                string y = ComputeImaginary(result);

                // Lookup imaginary unit
                string unit = result.Substring(result.Length - 1);
                unit = (unit == "i" || unit == "j") ? unit : "i";

                try
                {
                    // Return error if either coefficient is not a number
                    if (x == ErrorStrings[4].ToString() || y == ErrorStrings[4].ToString()) return ErrorStrings[4].ToString();
                    double a = double.Parse(x);
                    double b = double.Parse(y);

                    //double real = double.Parse(num) * Math.Log(this.Abs1());
                    //double imag = double.Parse(num) * this.Arg1();
                    //double scalar = Math.Exp(real);


                    //double real = double.Parse(num) * Math.Log(a);
                    //double imag = double.Parse(num) * b;

                    //double scalar = Math.Exp(real);


                    // return new Complex(scalar * Math.Cos(imag), scalar * Math.Sin(imag));

                    double r = Math.Sqrt(((a * a) + (b * b)));
                    // double angle = b / a;
                    double angle = Math.Atan2(b, a);
                    string r1 = ComputeRound((Math.Pow(r, double.Parse(num)) * double.Parse(ComputeCos((angle * double.Parse(num)).ToString()))).ToString());
                    string r2 = ComputeRound((Math.Pow(r, double.Parse(num)) * double.Parse(ComputeSin((angle * double.Parse(num)).ToString()))).ToString());

                    // double e = Math.Exp(a);

                    //double r1 = Math.Pow(e, double.Parse(num));
                    //double r2 = double.Parse(ComputeImArgument(result));

                    string args = r1 + ParseArgumentSeparator + r2 + ParseArgumentSeparator + unit;
                    // Return sine of complex number

                    return ComputeComplex(args);
                }

                catch
                {                    
                    if (ComputeIsText(result) == TRUEVALUESTR || ComputeIsText(num) == TRUEVALUESTR)
                        return ErrorStrings[5].ToString();
                    else if (result == "" || num == "")
                        return ErrorStrings[1].ToString();
                    else
                        return this.ErrorStrings[1].ToString();
                }
            }


            /// <summary>
            /// Compares the given two values
            /// </summary>
            /// <param name="argList">Two Numbers to be compared.</param>
            /// <returns>Returns the result of the comparision in the form of 0 or 1</returns>
            public string Gestep(string argList)
            {
#if _ENABLETIMERS
            string ML = "Gestep"; MarkTimeStart(ML);
#endif
                string[] ranges = argList.Split(new char[] { ParseArgumentSeparator });
                string result, step;
                double number, step1;
                try
                {
                    if (ranges.Length > 2 || ranges.Length < 1)
                        return FormulaErrorStrings[10].ToString();
                    else if (ranges.Length == 1)
                    {
                        result = this.GetValueFromArg(ranges[0]);
                        number = double.Parse(result);
                        step1 = 0;
                    }
                    else
                    {
                        result = this.GetValueFromArg(ranges[0]);
                        step = this.GetValueFromArg(ranges[1]);
                        number = double.Parse(result);
                        step1 = double.Parse(step);
                    }

                    return (number >= step1) ? "1" : "0";
                }
                catch
                {

#if _ENABLETIMERS
               MarkTimeEnd(ML);
#endif
                    return this.FormulaErrorStrings[21].ToString();
                }
            }
