                    if (ranges.Length == 1)
                    {
                        x = this.GetValueFromArg(ranges[0]);
                        nn = "0";
                    }
                    else
                        return FormulaErrorStrings[10].ToString();

                double result = 0;
                double k = 0;
                double kf = 0;
                double nk1f = 0;
                double nkf = 0;
                double zn = 0;
                double t = 0;
                double s = 0;
                double z0 = 0;
                double z = 0;
                double ans = 0;
                double fn = 0;
                double pn = 0;
                double pk = 0;
                double zmn = 0;
                double tlg = 0;
                double tox = 0;
                int i = 0;
                string n;
                double eul = 0;

                eul = 5.772156649015328606065e-1;
                if (int.Parse(nn) < 0)
                {
                    n = "-" + nn;
                }
                else
                {
                    n = nn;
                }
                //alglib.ap.assert(n <= 31, "Overflow in BesselKN");
                //alglib.ap.assert((double)(x) > (double)(0), "Domain error in BesselKN");
                if (double.Parse(x) <= 9.55)
                {
                    ans = 0.0;
                    z0 = 0.25 * double.Parse(x) * double.Parse(x);
                    fn = 1.0;
                    pn = 0.0;
                    zmn = 1.0;
                    tox = 2.0 / double.Parse(x);
                    if (double.Parse(n) > 0)
                    {
                        pn = -eul;
                        k = 1.0;
                        for (i = 1; i <= double.Parse(n) - 1; i++)
                        {
                            pn = pn + 1.0 / k;
                            k = k + 1.0;
                            fn = fn * k;
                        }
                        zmn = tox;
                        if (double.Parse(n) == 1)
                        {
                            ans = 1.0 / double.Parse(x);
                        }
                        else
                        {
                            nk1f = fn / double.Parse(n);
                            kf = 1.0;
                            s = nk1f;
                            z = -z0;
                            zn = 1.0;
                            for (i = 1; i <= double.Parse(n) - 1; i++)
                            {
                                nk1f = nk1f / (double.Parse(n) - i);
                                kf = kf * i;
                                zn = zn * z;
                                t = nk1f * zn / kf;
                                s = s + t;
                                // alglib.ap.assert((double)(math.maxrealnumber - Math.Abs(t)) > (double)(Math.Abs(s)), "Overflow in BesselKN");
                                //  alglib.ap.assert(!((double)(tox) > (double)(1.0) && (double)(math.maxrealnumber / tox) < (double)(zmn)), "Overflow in BesselKN");
                                zmn = zmn * tox;
                            }
                            s = s * 0.5;
                            t = Math.Abs(s);
                            //alglib.ap.assert(!((double)(zmn) > (double)(1.0) && (double)(math.maxrealnumber / zmn) < (double)(t)), "Overflow in BesselKN");
                            //alglib.ap.assert(!((double)(t) > (double)(1.0) && (double)(math.maxrealnumber / t) < (double)(zmn)), "Overflow in BesselKN");
                            ans = s * zmn;
                        }
                    }
                    tlg = 2.0 * Math.Log(0.5 * double.Parse(x));
                    pk = -eul;
                    if (double.Parse(n) == 0)
                    {
                        pn = pk;
                        t = 1.0;
                    }
                    else
                    {
                        pn = pn + 1.0 / double.Parse(n);
                        t = 1.0 / fn;
                    }
                    s = (pk + pn - tlg) * t;
                    k = 1.0;
                    do
                    {
                        t = t * (z0 / (k * (k + double.Parse(n))));
                        pk = pk + 1.0 / k;
                        pn = pn + 1.0 / (k + double.Parse(n));
                        s = s + (pk + pn - tlg) * t;
                        k = k + 1.0;
                    }

                    while ((double)(Math.Abs(t / s)) > (double)(machineepsilon));
                    s = 0.5 * s / zmn;
                    if (double.Parse(n) % 2 != 0)
                    {
                        s = -s;
                    }
                    ans = ans + s;
                    result = ans;
                    return result.ToString();
                }
                if (double.Parse(x) > (double)(Math.Log(maxrealnumber)))
                {
                    result = 0;
                    return result.ToString();
                }
                k = double.Parse(n);
                pn = 4.0 * k * k;
                pk = 1.0;
                z0 = 8.0 * double.Parse(x);
                fn = 1.0;
                t = 1.0;
                s = t;

                i = 0;
                do
                {
                    z = pn - pk * pk;
                    t = t * z / (fn * z0);
                    nk1f = Math.Abs(t);
                    if (i >= double.Parse(n) && (double)(nk1f) > (double)(nkf))
                    {
                        break;
                    }
                    nkf = nk1f;
                    s = s + t;
                    fn = fn + 1.0;
                    pk = pk + 2.0;
                    i = i + 1;
                }
                while ((double)(Math.Abs(t / s)) > (double)(machineepsilon));
                string neg = "-" + x;
                result = Math.Exp(double.Parse(neg)) * Math.Sqrt(Math.PI / (2.0 * double.Parse(x))) * s;

                return result.ToString();
            }

