            /// <summary>
            /// Return the XML content of the given document
            /// </summary>
            /// <param name="argList">web link</param>
            /// <returns>XML data</returns>
            public string ComputeWebService(string argList)
            {                
                string[] args = SplitArgsPreservingQuotedCommas(argList);
                int argCount = args.GetLength(0);
                if (argCount != 1)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string text = this.StripTics0(GetValueFromArg(args[0]));
                //text = System.Uri.EscapeDataString(text);
                //text = text.Replace("+", "%20");
                if (text.StartsWith("ftp") || text.StartsWith("file"))
                {
                    return this.ErrorStrings[1].ToString();
                }

                WebClient myWebClient = new WebClient();

                // Download home page data.
                download = string.Empty;
                try
                {
                    // Download the Web resource and save it into a data buffer.
#if !SILVERLIGHT
                    byte[] myDataBuffer = myWebClient.DownloadData(text);
                    download = Encoding.ASCII.GetString(myDataBuffer);
#else                
                myWebClient.DownloadStringAsync(new Uri(text));
#endif
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
                return download;
            }

