            public string ComputeJis(string arg)
            {
                string[] args = SplitArgsPreservingQuotedCommas(arg);
                int argCount = args.GetLength(0);
                if (argCount != 1)               
                    return this.FormulaErrorStrings[wrong_number_arguments];
                
                string firstStr = this.StripTics0(GetValueFromArg(args[0]));
                string strReturn = "";

                char[] dbcChr = firstStr.ToCharArray();
                for (int i = 0; i < dbcChr.Length; i++)
                {
                    if (dbcChr[i] == 32)
                    {
                        dbcChr[i] = (char)12288;
                        continue;
                    }
                    if (dbcChr[i] < 127)
                        dbcChr[i] = (char)(dbcChr[i] + 65248);
                }
                strReturn = new string(dbcChr);

                return strReturn;
            }

