            /// <summary>
            /// Returns a substring of the given string.
            /// </summary>
            /// <param name="range">Contains the original string, start position of the substring,
            /// and the number of characters in the substring.</param>
            /// <returns>A substring.</returns>
            public string ComputeMidB(string range)
            {
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount != 3)             
                    return this.FormulaErrorStrings[invalid_arguments];                

                string s1 = args[0];
                s1 = this.GetValueFromArg(s1);
                bool hasTics = s1.StartsWith(this.TIC) && s1.EndsWith(this.TIC);
                string s2 = this.GetValueFromArg(args[2]);
                int len = int.Parse(s2);
                if (args[1].IndexOf("#VALUE!") > -1)                
                    return this.ErrorStrings[1].ToString();                

                s2 = this.GetValueFromArg(args[1]);
                int start = int.Parse(s2) + (hasTics ? 0 : -1);

                if (start + len > s1.Length)
                {
                    return this.FormulaErrorStrings[invalid_arguments];
                }

                s1 = s1.Substring(start, len);
                if (hasTics && !s1.StartsWith(this.TIC))
                {
                    s1 = this.TIC + s1;
                }

                if (hasTics && !s1.EndsWith(this.TIC))
                {
                    s1 = s1 + this.TIC;
                }

                return s1;
            }
            
            /// <summary>
            /// Returns the right so many characters in the given string.
            /// </summary>
            /// <param name="range">Contains the string and the number of characters.</param>
            /// <returns>A right substring.</returns>
            public string ComputeRightB(string range)
            {
                string[] args = SplitArgsPreservingQuotedCommas(range);
                int argCount = args.GetLength(0);
                if (argCount != 1 && argCount != 2)
                    return this.FormulaErrorStrings[invalid_arguments];                

                string s1 = args[0];
                s1 = this.GetValueFromArg(s1);
                bool hasTics = s1.StartsWith(this.TIC) && s1.EndsWith(this.TIC);
                string s2 = (argCount == 2) ? args[1] : "1";
                if (s2.IndexOf("#VALUE!") > -1)                
                    return this.ErrorStrings[1].ToString();                

                s2 = this.ComputedValue(s2);

                int len = int.Parse(s2) + (hasTics ? 1 : 0);
                int start = (s1.Length >= len) ? s1.Length - len : 0;
                s1 = s1.Substring(start);
                if (hasTics && !s1.StartsWith(this.TIC))
                {
                    s1 = this.TIC + s1;
                }

                return s1;
            }

            /// <summary>
            /// Convert the text to number
            /// </summary>
            /// <param name="argList">text, </param>
            /// <returns>decimal separator,group separator </returns>
            public string ComputeNumberValue(string argList)
            {
                string[] args = SplitArgsPreservingQuotedCommas(argList);
                int argCount = args.GetLength(0);
                char decimalseparator = ParseDecimalSeparator;
                char groupseparator = ParseArgumentSeparator;
                if (argCount > 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string text = this.StripTics0(GetValueFromArg(args[0]));
                if (argCount > 1)
                {
                    try
                    {
                        string deci = this.StripTics0(GetValueFromArg(args[1]));
                        string gro = this.StripTics0(GetValueFromArg(args[2]));
                        if ((deci.Equals("invalid expression") || gro.Equals("invalid expression")) || (string.IsNullOrEmpty(deci) && string.IsNullOrEmpty(gro)))
                        {
                            return this.ErrorStrings[1].ToString();
                        }
                        else
                        {
                            decimalseparator = this.StripTics0(deci)[0];
                            groupseparator = this.StripTics0(gro)[0];
                        }
                    }
                    catch (Exception)
                    {
                        return this.ErrorStrings[1].ToString();
                    }
                }
                if (string.IsNullOrEmpty(text))
                {
                    return "0";
                }
                int indexDecimal = text.IndexOf(decimalseparator);
                int indexGroup = text.IndexOf(groupseparator);
                if ((indexGroup >= indexDecimal) && (indexDecimal != -1 || indexGroup != -1))
                    return this.ErrorStrings[1].ToString();
                
                text = text.Replace(this.TIC, string.Empty);
                text = text.Replace(" ", string.Empty);
                text = text.Replace(groupseparator.ToString(), string.Empty);
                text = text.Replace(decimalseparator, ParseDecimalSeparator);
                string compText = this.ComputeValue(text);
                if (ComputeIsNumber(compText) != this.TRUEVALUESTR || text.EndsWith("$"))
                {
                    TimeSpan ts;
                    if (TimeSpan.TryParse(text, out ts))
                    {
                        return ts.TotalDays.ToString();
                    }               
                    return this.ErrorStrings[1].ToString();
                }
                return compText;
            }

