                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                if (argList.Length > 15)
                {
                    return this.ErrorStrings[4].ToString();// "#NUM!";
                }
                string result = string.Empty;
                string d = this.GetValueFromArg(args[0]);
                double truncate; decimal decTrunc;
                if (double.TryParse(d, out truncate))
                {
                    result = truncate.ToString();
                }
                else if (decimal.TryParse(d, out decTrunc))
                {
                    result = decTrunc.ToString();
                }
                return result.ToString();
            }
