            public string ComputeBase(string argList)
            {
                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount > 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                int number = 0, radix = 0, length = 1;
                try
                {
                    number = int.Parse(this.GetValueFromArg(args[0]).Replace(this.TIC, ""));
                    radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
                    length = (argCount == 3) ? int.Parse(this.GetValueFromArg(args[2]).Replace(this.TIC, "")) : 1;
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
                const int BitsInLong = 64;
                const string Digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";

                if (radix < 2 || radix > Digits.Length)
                {
                    return this.ErrorStrings[1].ToString();
                }

                if (number == 0)
                    return "0";

                int index = BitsInLong - 1;
                long currentNumber = Math.Abs(number);
                char[] charArray = new char[BitsInLong];

                while (currentNumber != 0)
                {
                    int remainder = (int)(currentNumber % radix);
                    charArray[index--] = Digits[remainder];
                    currentNumber = currentNumber / radix;
                }

                string result = new String(charArray, index + 1, BitsInLong - index - 1);
                StringBuilder outputString = new StringBuilder();
                for (int i = 0; i < length - result.Length; i++)
                {
                    outputString.Append("0");
                }
                result = outputString.ToString() + result;
                if (number < 0)
                {
                    result = "-" + result;
                }
                return result.ToString();
            }

            public string ComputeDecimal(string argList)
            {
                string[] args = argList.Split(new char[] { ParseArgumentSeparator });
                int argCount = args.GetLength(0);
                if (argCount > 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                const string Base64 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz+/";

                string strValue; int radix = 0;
                try
                {
                    strValue = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
                    radix = int.Parse(this.GetValueFromArg(args[1]).Replace(this.TIC, ""));
                }
                catch (Exception)
                {
                    return this.ErrorStrings[1].ToString();
                }
                int result;
                if (radix < 2 || radix > Base64.Length)
                {
                    return this.ErrorStrings[4].ToString();
                }
                strValue = strValue.Trim();
                if (radix <= 36)
                    strValue = strValue.ToUpper();
                int pos = 0;
                result = 0;
                // Use lookup table to parse string
                while (pos < strValue.Length && !Char.IsWhiteSpace(strValue[pos]))
                {
                    string digit = strValue.Substring(pos, 1);
                    int i = Base64.IndexOf(digit);
                    if (i >= 0 && i < radix)
                    {
                        result *= radix;
                        result += i;
                        pos++;
                    }
                    else
                    {
                        return this.ErrorStrings[4].ToString();
                    }
                }
                return result.ToString();
            }
            public string ComputeArabic(string arg)
            {
                string[] args = arg.Split(new char[] { ParseArgumentSeparator });
                if (args.Length != 1)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string text = GetValueFromArg(args[0]).Replace(this.TIC, "").ToUpper();
                int i = 0;
                string ch = null;
                long result = 0;
                long new_value = 0;
                long old_value = 0;
                old_value = 1000;
                for (i = 1; i <= text.Length; i++)
                {
                    // See what the next character is worth.
                    ch = text.Substring(i - 1, 1);
                    switch (ch)
                    {
                        case "I":
                            new_value = 1;
                            break;
                        case "V":
                            new_value = 5;
                            break;
                        case "X":
                            new_value = 10;
                            break;
                        case "L":
                            new_value = 50;
                            break;
                        case "C":
                            new_value = 100;
                            break;
                        case "D":
                            new_value = 500;
                            break;
                        case "M":
                            new_value = 1000;
                            break;
                        default:
                            {
                                return this.ErrorStrings[1].ToString();
                            }
                    }
                    // See if this character is bigger
                    // than the previous one.
                    if (new_value > old_value)
                    {
                        // The new value > the previous one.
                        // Add this value to the result
                        // and subtract the previous one twice.
                        result = result + new_value - 2 * old_value;
                    }
                    else
                    {
                        // The new value <= the previous one.
                        // Add it to the result.
                        result = result + new_value;
                    }
                    old_value = new_value;
                }
                return result.ToString();
            }

            public string ComputeCeilingMath(string args)
            {
                string[] range = args.Split(new char[] { ParseArgumentSeparator });
                int argCount = range.GetLength(0);
                if (argCount > 3 && argCount < 1)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string number = this.GetValueFromArg(range[0]).Replace(this.TIC, "");
                string sign = (argCount > 1) ? this.GetValueFromArg(range[1]).Replace(this.TIC, "") : "1";
                string mode = (argCount == 3) ? this.GetValueFromArg(range[2]).Replace(this.TIC, "") : "1";
                double d1, d2 = 0, d3 = 0, result;
                if (!(double.TryParse(number, out d1) && double.TryParse(sign, out d2) && double.TryParse(mode, out d3)))
                {
                    return "#VALUE!";
                }
                if (d1 < 0 && d3 < 0)
                {
                    d2 = -1;
                }
                result = double.Parse(ComputeCeiling(d1.ToString() + ParseArgumentSeparator + d2.ToString()));
                return result.ToString();
            }

