                        length2 = arrayValue.Length;
                        if (length1 != length2)
                        {
                            return this.FormulaErrorStrings[wrong_number_arguments];
                        }
                        for (int v = 0; v < length1; v++)
                        {
                            matrix[i, v] = double.Parse(this.GetValueFromArg(arrayValue[v]));
                        }
                    }

                    det = this.determinant(matrix, arrayArg.Length);
                }
                return det.ToString();
            }

            private double determinant(double[,] a, int n)
            {
                double res = 0;
                if (n == 1)
                    res = a[0, 0];
                // Trivial 2x2 matrix
                else if (n == 2)
                    res = a[0, 0] * a[1, 1] - a[1, 0] * a[0, 1];
                // NxN matrix
                else
                {
                    res = 0;
                    for (int j1 = 0; j1 < n; j1++)
                    {
                        double[,] m = generateSubArray(a, n, j1);
                        res += Math.Pow(-1.0, 1.0 + j1 + 1.0) * a[0, j1] * determinant(m, n - 1);
                    }
                }
                return res;
            }
            private double[,] generateSubArray(double[,] a, int N, int j1)
            {
                double[,] m = new double[N - 1, 3];
                //for (int k=0; k<N-1; k++)
                //        m[k] = new double[N-1];

                for (int i = 1; i < N; i++)
                {
                    int j2 = 0;
                    for (int j = 0; j < N; j++)
                    {
                        if (j == j1)
                            continue;
                        m[i - 1, j2] = a[i, j];
                        j2++;
                    }
                }
                return m;
            }
