            public string ComputeWeeknum(string argList)
            {
                string[] args = SplitArgsPreservingQuotedCommas(argList);
                int argCount = args.GetLength(0);
                if (argCount > 2)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
                string weekDate = this.GetValueFromArg(args[0]).Replace(this.TIC, "");
                if (weekDate.Equals("invalid expression"))
                {
                    return this.ErrorStrings[1].ToString();
                }
                DateTime weekDateTime, firstDate = this.dateTime1900; ;
                if (!(DateTime.TryParse(weekDate, CultureInfo.CurrentCulture, DateTimeStyles.None, out weekDateTime)))
                {
                    try
                    {
                        int weeknumber = int.Parse(weekDate);
                        return ((weeknumber / 7) + 1).ToString();
                    }
                    catch (Exception)
                    {
                        return this.ErrorStrings[4].ToString();
                    }
                }
                ArrayList weekStart = new ArrayList();
                weekStart.AddRange(new string[] 
            {
            "","0","1","","","","","","","","","1","2","3","4","5","6","0","","","","1"
        });
                int weektype = 0;
                if (!(argCount == 2 && int.TryParse(GetValueFromArg(args[1]), out weektype)))
                {
                    weektype = 1;
                }
                int weehStartValue = int.Parse(weekStart[weektype].ToString());
                firstDate = new DateTime(weekDateTime.Year, 1, 1);
                int firstDay = firstDate.Day;
                int offset = (firstDay < weehStartValue) ? weehStartValue - firstDay + 1 : firstDay - weehStartValue;
                TimeSpan ts = new TimeSpan(offset, 0, 0, 0);
                DateTime dt = firstDate.Subtract(ts);
                double noofDays = double.Parse(this.ComputeDatevalue(weekDate)) - double.Parse(this.ComputeDatevalue(dt.ToString()));
                double dval = Math.Floor(noofDays / 7) + 1 + weehStartValue;
                return dval.ToString();
            }
