                {
                    try
                    {
                        double first = double.Parse(startDate);
                        return ((int)(first + temp)).ToString();
                    }
                    catch (Exception)
                    {
                        return this.ErrorStrings[1].ToString();
                    }
                }
                int totalDays = (int)temp;
                if (argCount == 4)
                {
                    adjustRange = args[3];
                    this.AdjustRangeArg(ref adjustRange);
                    ////is a cellrange
                    if (adjustRange.IndexOf(':') > -1 || adjustRange.IndexOf(',') > -1)
                    {
                        foreach (string s in this.GetCellsFromArgs(adjustRange))
                        {
                            try
                            {
                                s1 = this.GetValueFromArg(s).Replace(this.TIC, string.Empty);
                            }
                            catch (Exception ex)
                            {
                                return ex.Message;
                            }

                            if (s1 != string.Empty)
                            {
                                if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1)
                                {
                                    holidays.Add(date);
                                }
                            }
                        }
                    }
                    else
                    {
                        try
                        {
                            s1 = this.GetValueFromArg(adjustRange).Replace(this.TIC, string.Empty);
                        }
                        catch (Exception ex)
                        {
                            return ex.Message;
                        }

                        if (s1.Length > 0)
                        {
                            if (DateTime.TryParse(s1, out date) && !holidays.Contains(date) && date.CompareTo(startDateTime) != -1)
                            {
                                holidays.Add(date);
                            }
                        }
                    }
                }
                int weekend = -1;
                if (!(argCount > 2 && int.TryParse(args[2], out weekend)))
                {
                    weekend = 1;
                }
                if (weekend == 0)
                {
                    return this.ErrorStrings[4].ToString();
                }
                ArrayList weekendDays = new ArrayList();
                weekendDays.AddRange(SplitArguments(WeekEndType[weekend].ToString(), ','));
                int j = 0;
                DateTime tempStartDate = startDateTime;
                while (j < totalDays)
                {
                    tempStartDate = tempStartDate.AddDays(1);
                    int dayofweek = (int)tempStartDate.DayOfWeek;
                    if (weekendDays.IndexOf(dayofweek.ToString()) < 0 && holidays.IndexOf(tempStartDate) < 0)
                    {
                        j++;
                    }
                }
#if SILVERLIGHT
            return ComputeDatevalue(tempStartDate.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern));
#else
                return ComputeDatevalue(tempStartDate.ToShortDateString());
#endif
            }

            /// <summary>
            /// returns the fraction of the year represented by the number of whole days between two given dates
            /// </summary>
            /// <param name="argList">startDate, endDate, basis (optional)</param>
            /// <returns>returns the fraction of the year</returns>
            public string ComputeYearFrac(string argList)
            {
                string[] args = SplitArgsPreservingQuotedCommas(argList);
                int argCount = args.GetLength(0);
                List<DateTime> holidays = new List<DateTime>();
                double yearFracValue = 0;
                if (argCount != 2 && argCount > 3)
                {
                    return this.FormulaErrorStrings[wrong_number_arguments];
                }
#if !SILVERLIGHT
                string startDate = this.GetValueFromArg(args[0].Replace(this.TIC, ""));
                string endDate = this.GetValueFromArg(args[1].Replace(this.TIC, ""));
                string basis = (argCount == 3) ? this.GetValueFromArg(args[2]).Replace(this.TIC, "") : "0";
                DateTime startDateTime = dateTime1900;
                DateTime endDateTime = dateTime1900;
                double basisValue;
                double startDateValue = -1;
                double endDateValue = -1;
                if (!((double.TryParse(startDate, out startDateValue) || DateTime.TryParse(startDate, CultureInfo.CurrentCulture, DateTimeStyles.None, out startDateTime))
                    && (DateTime.TryParse(endDate, CultureInfo.CurrentCulture, DateTimeStyles.None, out endDateTime) || double.TryParse(endDate, out endDateValue)) && double.TryParse(basis, out basisValue)))
                {
                    return this.ErrorStrings[1].ToString();
                }
                if ((basisValue > 4 && basisValue < 0))
                    return this.ErrorStrings[4].ToString();
                
                if (startDateValue > 0)
                {
                    startDateTime = dateTime1900;
                    startDate = startDateTime.ToShortDateString();
                }
                if (endDateValue > 0)
                {
                    endDateTime = dateTime1900.AddDays(endDateValue);
                    endDate = endDateTime.ToShortDateString();
                }
                double noofDays = double.Parse(this.ComputeDatevalue(endDate)) - double.Parse(this.ComputeDatevalue(startDate));
                if (noofDays < 0)
                {
                    startDateTime = DateTime.Parse(endDate);
                    endDateTime = DateTime.Parse(startDate);
                }
                double startYear = startDateTime.Year;
                double startMonth = startDateTime.Month;
                double startDay = startDateTime.Day;
                double endYear = endDateTime.Year;
                double endMonth = endDateTime.Month;
                double endDay = endDateTime.Day;
                double startDatysInMonth = DateTime.DaysInMonth(startDateTime.Year, startDateTime.Month);
                double endDaysInMonth = DateTime.DaysInMonth(endDateTime.Year, endDateTime.Month);
                switch (basis)
                {
                    case "0":
                        if (startDay == 31 && endDay == 31)
                        {
                            startDay = 30;
                            endDay = 30;
                        }
                        else if (startDay == 31)
                        {
                            startDay = 30;
                        }
                        else if (startDay == 30 && endDay == 31)
                        {
                            endDay = 30;
                        }
                        else if (startMonth == 1 && endMonth == 1 && startDatysInMonth == startDay && endDaysInMonth == endDay)
                        {
                            startDay = 30;
                            endDay = 30;
                        }
                        else if (startMonth == 1 && startDatysInMonth == startDay)
                        {
                            startDay = 30;
                        }
                        yearFracValue = ((endDay + endMonth * 30 + endYear * 360) - (startDay + startMonth * 30 + startYear * 360));
                        yearFracValue = yearFracValue / 360;
                        break;
                    case "1":
                        double ylength = 366;
                        if (startYear == endYear || ((startYear + 1) == endYear) && ((startMonth > endMonth) || ((startMonth == endMonth) && (startDay >= endDay))))
                        {
                            if (startYear == endYear && DateTime.IsLeapYear(int.Parse(startYear.ToString())))
                            {
                                ylength = 366;
                            }
                            else if (Daysfeb29(startDateTime, endDateTime) || (endMonth == 1 && endDay == 29))
                            {
                                ylength = 366;
                            }
                            yearFracValue = noofDays / ylength;
                        }
                        else
                        {
                            double years = (endYear - startYear) + 1;
                            DateTime newEndTime = new DateTime(endDateTime.Year + 1, 0, 1);
                            DateTime newStartTime = new DateTime(startDateTime.Year + 1, 0, 1);
#if SILVERLIGHT
                        double days = double.Parse(this.ComputeDatevalue(newEndTime.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern))) - double.Parse(this.ComputeDatevalue(newStartTime.ToString(System.Globalization.DateTimeFormatInfo.CurrentInfo.ShortDatePattern)));
#else
                            double days = double.Parse(this.ComputeDatevalue(newEndTime.ToShortDateString())) - double.Parse(this.ComputeDatevalue(newStartTime.ToShortDateString()));
#endif
                            double average = days / years;
                            yearFracValue = noofDays / average;
                        }
                        break;
                    case "2":
                        yearFracValue = noofDays / 360;
                        break;
                    case "3":
                        yearFracValue = noofDays / 365;
                        break;
                    case "4":
                        if (startDay == 31)
                            startDay = 30;
                        if (endDay == 31)
                            endDay = 30;
                        // Remarkably, do NOT change February 28 or February 29 at ALL
                        yearFracValue = ((endDay + endMonth * 30 + endYear * 360) - (startDay + startMonth * 30 + startYear * 360)) / 360;
                        break;
                    default:
                        break;
                }
#endif
                return yearFracValue.ToString();
            }

