            /// <summary>
            /// Returns the number of days since 01 Jan 1900.
            /// </summary>
            /// <param name="argList">Text containing a date.</param>
            /// <returns>Number of days.</returns>
            public string ComputeDatevalue(string argList)
            {
                argList = argList.Replace(this.TIC, string.Empty);
                DateTime dt;
                try
                {
                    if (!DateTime.TryParse(argList, out dt))
                    {
                        string[] ranges = argList.Split(ParseDateTimeSeparator);
                        int argCount = ranges.GetLength(0);
                        string arg = string.Empty;
                        for (int i = 0; i < argCount; ++i)
                        {
                            ranges[i] = this.ComputedValue(ranges[i]);
                            if (i < argCount - 1)
                                arg += ranges[i] + ParseDateTimeSeparator;
                            else
                                arg += ranges[i];
                        }
                        arg = arg.Replace(TIC, string.Empty);
                        dt = DateTime.Parse(arg);
                    }

                }
                catch
                {
                    return this.FormulaErrorStrings[this.invalid_arguments];
                }

                int days = 1 + ((TimeSpan)(dt - this.dateTime1900)).Days;
                if (Treat1900AsLeapYear && days > 59)
                {
                    days += 1;
                }

                return days.ToString();
            }

