            /// <summary>
            /// Determines whether the given string is Even number or Not. 
            /// </summary>
            /// <param name="range">A string to be tested.</param>
            /// <returns>TRUE if the string is Even Number, otherwise returns False</returns>
            public string ComputeIsEven(string range)
            {
                double d;
                DateTime dateValue;
