                }
                catch
                {
                }

                if (double.TryParse(range, NumberStyles.Any, null, out d))
                {
                    int value = (int)d;
                    if (value % 2 == 0)
                        return TRUEVALUESTR;
                    else
                        return FALSEVALUESTR;
                }
                else if (DateTime.TryParse(range, out dateValue))
                {
                    d = GetSerialDateTimeFromDate(dateValue);
                    int value = (int)d;
                    if (value % 2 == 0)
                        return TRUEVALUESTR;
                    else
                        return FALSEVALUESTR;
                }
                else if (range == string.Empty)
                    return TRUEVALUESTR;
                else
                    return "#VALUE?";

            }

