            {
                string s = GetValueFromArg(args);
                string pattern = @"[a-zA-Z!#$%&'()*+,/:;<=>?@\^_`{|}~-]";
                if (Regex.IsMatch(s, pattern))
                {
                    //Console.WriteLine("String");
                    return s;
                }
                else
                {
                    //Console.WriteLine("Digit");
                    return string.Empty;
                }
            }

