            /// <summary>
            /// Returns the row index of the passed in cell reference.
            /// </summary>
            /// <param name="arg">Contains zero or one argument. If no argument is passed, returns the row index of the
            /// location of this Row function cell, otherwise returns the row index of the passed in cell reference.</param>
            /// <returns>The row index.</returns>
            /// <remarks>
            /// This method doesn't return an array of row numbers as the array formula entry is not supported in engine. It is another usecase of this library function.
            /// </remarks>
            public string ComputeRow(string arg)
            {
                string[] args = SplitArgsPreservingQuotedCommas(arg);
                int argCount = args.GetLength(0);
                if (argCount != 1)              
                    return this.FormulaErrorStrings[wrong_number_arguments];
                
                if (string.IsNullOrEmpty(args[0]))                
                    return this.RowIndex(this.cell).ToString();                

                if (!this.IsCellReference(args[0]) && !this.NamedRanges.ContainsKey(args[0]))
                    return this.FormulaErrorStrings[invalid_arguments];
                
                if (arg.IndexOf(':') > -1)                
                    arg = this.GetCellsFromArgs(arg)[0]; //considers first cell reference from the range of cells.                

                return this.RowIndex(arg).ToString();
            }

            /// <summary>
            /// Converts a value to a number.
            /// </summary>
            /// <param name="args">Value to convert.</param>
            /// <returns>Converted string.</returns>
            public string ComputeN(string args)
            {
                string s = GetValueFromArg(args);
                int integerValue;
                double doubleValue;
                DateTime dateTimeValue;
                bool booleanValue;
                if (int.TryParse(s, out integerValue))
                {
                    return integerValue.ToString();
                }
                else if (double.TryParse(s, out doubleValue))
                {
                return doubleValue.ToString();
                }
                else if(DateTime.TryParse(s,out dateTimeValue))
                {
                    integerValue = GetSerialDateFromDate(dateTimeValue.Year, dateTimeValue.Month, dateTimeValue.Day);
                    return integerValue.ToString();
                }
                else if (bool.TryParse(s,out booleanValue))
                {
                    if (booleanValue) 
                        return "1";
                    else 
                        return "0";
                }
                return "0";
            }


