            /// <summary>
            /// Returns a number corresponding to the predefined error values(#NULL!, #VALUE!, #REF!, #NAME?, #NUM!, #N/A, "#GETTING_DATA). Returns #N/A if not or any value enclosed within double quotes.
            /// </summary>            
            public string ComputeErrorType(string range)
            {
                string[] args = range.Split(new char[] { ParseArgumentSeparator });
                int argsCount = args.GetLength(0);
                if (argsCount != 1)
                    return FormulaErrorStrings[wrong_number_arguments];
                try
                {
                    range = GetValueFromArg(range);
                }
                catch{}

                if (range.Length > 1
                           && range[0] == this.TIC[0]
                           && range[range.Length - 1] == this.TIC[0])
                {
                    return "#N/A";
                }

                if (range.Equals("#NULL!"))
                    return "1";
                else if (range.Equals("#DIV/0!"))
                    return "2";
                else if (range.Equals("#VALUE!"))
                    return "3";
                else if (range.Equals("#REF!"))
                    return "4";
                else if (range.Equals("#NAME?"))
                    return "5";
                else if (range.Equals("#NUM!"))
                    return "6";
                else if (range.Equals("#N/A"))
                    return "7";
                else if (range.Equals("#GETTING_DATA"))
                    return "8";
                return "#N/A";                
            }

            /// <summary>
            /// Removes all leading and trailing white-space characters.
            /// </summary>
            /// <param name="args">Value to trim.</param>
            /// <returns>
            /// The string that remains after all leading and trailing white-space characters
            /// were removed.
            ///</returns>
            public string ComputeTrim(string args)
            {
                string s = GetValueFromArg(args).Trim(new char[] { '\"', ' ' });
                int len = 0;
                //strip out interior double, triple, etc spaces...
                while (s.Length != len)
                {
                    len = s.Length;
                    s = s.Replace("  ", " ");
                }
                return s;
            }

