                                        if (ParsePossibleEmptyStrings(s1, s2, out d, out d1))
                                        {
                                            val = (d1 > d) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                        else
                                        {
                                            val = (s1.ToUpper().Replace(TIC, "").CompareTo(s2.ToUpper().Replace(TIC, "")) > 0) ? TRUEVALUESTR : FALSEVALUESTR;
                                        }
                                        _stack.Push(val);
                                        i = i + 1;
                                    }
                                    break;
                                case TOKEN_equal:
                                    {
                                        string s1 = PopString(_stack);
