                                ////								string s = PopString(_stack); 
                                ////								bool b = true;
                                ////								if (s.Length == 0 && s1.Length == 0)
                                ////									b = true;
                                ////								else if (s.Length == 0 || s1.Length == 0)
                                ////									b = false;
                                ////								else
                                ////								{
                                ////									if (regexValue == null || oldregexValueCompare != s1)
