                                ////								int val = (b) ? TRUEVALUE : FALSEVALUE;
                                ////								_stack.Push(val.ToString());
                                ////								i = i + 1;
                                ////							} 
                                ////								break;
                                ////							case TOKEN_in://in uses Like
                                ////							{
                                ////								string s1 = PopString(_stack);
                                ////								string s = PopString(_stack); 
                                ////								bool b = false;
                                ////								if (s.Length == 0 && s1.Length == 0)
