                                ////								i = i + 1;
                                ////							} 
                                ////								break;
                                ////							case TOKEN_between: //handles dates - use TODAY for todays's date
                                ////							{
                                ////								string s1 = PopString(_stack);
                                ////								string s = PopString(_stack); 
                                ////								bool b = false;
                                ////								if (s.Length == 0 && s1.Length == 0)
                                ////									b = true;
